function hasColumn(table,col){ return db.prepare(`PRAGMA table_info(${table})`).all().some(x=>x.name===col); }
function addColumn(table,col,ddl){ if(!hasColumn(table,col)) db.exec(`ALTER TABLE ${table} ADD COLUMN ${col} ${ddl}`); }
function siteId(code){ return db.prepare('SELECT id FROM sites WHERE code=?').get(code)?.id || null; }
function actor(req,fallback='user'){return req?.user?.username||fallback}
function hashPassword(password,salt=crypto.randomBytes(16).toString('hex')){return {salt,hash:crypto.scryptSync(String(password),salt,64).toString('hex')}}
function verifyPassword(password,salt,expected){try{const got=crypto.scryptSync(String(password),salt,64);const exp=Buffer.from(expected,'hex');return got.length===exp.length&&crypto.timingSafeEqual(got,exp)}catch{return false}}
function tokenHash(token){return crypto.createHash('sha256').update(token).digest('hex')}
function sessionCookie(token,maxAge=28800){const secure=process.env.EHS_SECURE_COOKIE==='1'?'; Secure':'';return `ehs_session=${encodeURIComponent(token||'')}; HttpOnly; SameSite=Strict; Path=/; Max-Age=${maxAge}${secure}`}
function parseCookies(req){return Object.fromEntries(String(req.headers.cookie||'').split(';').map(x=>x.trim()).filter(Boolean).map(x=>{const i=x.indexOf('=');return [decodeURIComponent(i<0?x:x.slice(0,i)),decodeURIComponent(i<0?'':x.slice(i+1))]}))}
