function getKpiReport(year,month,site=''){
  const r=getMonthlyReport(year,month,site),siteId=site?db.prepare('SELECT id FROM sites WHERE code=?').get(site)?.id:null,siteClause=siteId?' AND site_id=?':'',siteArgs=siteId?[siteId]:[];
  const textRows=db.prepare(`SELECT title,category,status,progress,notes FROM tasks WHERE (due_date BETWEEN ? AND ? OR date(completed_at) BETWEEN ? AND ?)${siteClause}`).all(r.start,r.end,r.start,r.end,...siteArgs);const text=textRows.map(x=>`${x.title} ${x.category||''} ${x.notes||''}`).join(' | ').toLowerCase();
  const sds=r.documents.filter(d=>d.category==='chemical'&&/sds|msds/i.test(`${d.subcategory||''} ${d.original_name||''}`));const training=r.documents.filter(d=>d.category==='training'||/đào tạo|truyền thông|poster|clip/i.test(`${d.subcategory||''} ${d.original_name||''}`));const vehicle=textRows.filter(x=>/\bxe\b|bơm hàng|giao nhận|vận tải/i.test(`${x.title} ${x.notes||''}`));const f5=textRows.filter(x=>/5s/i.test(`${x.title} ${x.notes||''}`));const equip=textRows.filter(x=>/ứng phó|thiết bị|kiểm định|scba|pccc/i.test(`${x.title} ${x.notes||''}`));
  const evidence={vehicle:`${vehicle.length} task/ghi nhận liên quan xe trong hệ thống.`,ppe:`${r.summary.ppe_issue_transactions} lượt cấp PPE, tổng ${r.summary.ppe_issued_qty} đơn vị; ${r.summary.ppe_cost?`chi phí ${new Intl.NumberFormat('vi-VN').format(r.summary.ppe_cost)} đ.`:''}`,equipment:`${r.summary.inspections} lượt kiểm định/kiểm tra được ghi nhận; ${equip.length} task liên quan thiết bị/ứng phó.`,weekly:`${textRows.filter(x=>/báo cáo|report/i.test(`${x.title} ${x.notes||''}`)).length} task/ghi nhận báo cáo trong tháng.`,sds:`${sds.length} tài liệu SDS/MSDS được import trong tháng.`,training:`${training.length} tài liệu/ghi nhận đào tạo-truyền thông trong tháng.`,hr:'App chưa kết nối dữ liệu chấm công/HCNS; cần đối chiếu thủ công.',coordination:`${r.summary.tasks_completed} task hoàn thành; ${r.summary.documents_imported} tài liệu được cập nhật trong tháng.`, '5s':`${f5.length} task/ghi nhận có nội dung 5S trong tháng.`};
  return {...r,items:KPI_ITEMS.map(x=>({...x,result:evidence[x.key]||'',system_note:(x.key==='hr'||(!Number((evidence[x.key]||'').match(/^\d+/)?.[0])))?'Cần đối chiếu dữ liệu nguồn trước khi chấm điểm.':'Kết quả hệ thống chỉ là evidence hỗ trợ; điểm KPI do người đánh giá xác nhận.'}))};
}
function kpiReportSheets(year,month,site,filters,user){const r=getKpiReport(year,month,site),who=reporterInfo(filters,user),rows=[];rows.push([`ĐÁNH GIÁ KPI THÁNG ${String(r.month).padStart(2,'0')}/${r.year} - PHÒNG EHS`]);rows.push([`HỌ TÊN: ${who.reporter}`,'',`CHỨC DANH: ${who.position}`]);rows.push(['TT','Nội dung công việc','Mục tiêu','Đơn vị tính','Trọng số','Ghi chú','Kết quả thực hiện','Điểm theo mức độ hoàn thành chỉ tiêu','Điểm KPI']);rows.push(['A','CÔNG VIỆC KẾ HOẠCH','','','','','','','']);for(const x of r.items)rows.push([x.tt,x.work,x.target,x.unit,x.weight,x.system_note,x.result,'','']);rows.push(['B','Lỗi: được tính khi vi phạm các cam kết được thoả thuận trong kế hoạch được giao: chậm deadline/không báo cáo đầy đủ/không hoàn thành kế hoạch.','','','','','','','']);rows.push(['','TỔNG TRỌNG SỐ','','',r.items.reduce((a,x)=>a+x.weight,0),'','','','']);rows.push(['I','Điểm mục tiêu quy đổi','','','','','Để trống cho người đánh giá xác nhận','','']);rows.push(['II','Điểm hành động','','','','','','','']);rows.push(['III','Điểm KPI','','','','','','','']);rows.push(['IV','Xếp loại','','','','','','','']);rows.push(['V','Tỷ lệ','','','','','','','']);rows.push(['','','GIÁM ĐỐC','TRƯỞNG BỘ PHẬN','','','','NGƯỜI LẬP',who.reporter]);return [{name:'KPI EHS',rows,headerRow:3,freezeRows:3,autoFilter:false,titleRows:[1,2]}]}


