  addColumn('ppe_transactions','employee_name_snapshot','TEXT');
  addColumn('ppe_transactions','department_snapshot','TEXT');
  addColumn('ppe_transactions','site_snapshot','TEXT');
  addColumn('ppe_transactions','snapshot_source','TEXT');
  addColumn('obligations','coordinator','TEXT');
  addColumn('obligations','schedule_year','INTEGER');
  addColumn('obligations','schedule_month','INTEGER');
  addColumn('obligations','source_stt','INTEGER');
  addColumn('obligations','source_goal','TEXT');
  addColumn('obligations','source_plan','TEXT');
  addColumn('obligations','legal_review_status',"TEXT NOT NULL DEFAULT 'not_reviewed'");
  addColumn('payments','weight_tolerance_kg',"REAL NOT NULL DEFAULT 0");
  addColumn('equipment','inspection_reminder_days',"INTEGER NOT NULL DEFAULT 30");
  addColumn('equipment','source_ref','TEXT');
  addColumn('equipment','review_status',"TEXT NOT NULL DEFAULT 'reviewed'");
  addColumn('equipment','source_country','TEXT');
