  addColumn('equipment','machine_description','TEXT');
  addColumn('equipment','control_number','TEXT');
  addColumn('equipment','reconciled_at','TEXT');
  addColumn('equipment','reconciled_by','TEXT');
  addColumn('document_extractions','original_fields_json','TEXT');
  addColumn('document_extractions','edited_by','TEXT');
  addColumn('document_extractions','edited_at','TEXT');
  addColumn('legal_sources','content_hash','TEXT');
  addColumn('legal_sources','last_checked_at','TEXT');
  addColumn('legal_sources','last_http_status','INTEGER');
  addColumn('legal_sources','last_error','TEXT');
  addColumn('legal_sources','etag','TEXT');
  addColumn('legal_sources','last_modified','TEXT');
  addColumn('obligations','progress',"INTEGER NOT NULL DEFAULT 0");
