  db.prepare(`UPDATE documents SET updated_at=COALESCE(updated_at,uploaded_at)`).run();
  db.exec(`
    UPDATE ppe_transactions SET unit_price_snapshot=(SELECT p.unit_price FROM ppe_items p WHERE p.id=ppe_transactions.item_id)
      WHERE type='OUT' AND unit_price_snapshot IS NULL;
    UPDATE ppe_transactions SET cost_amount=quantity*unit_price_snapshot
      WHERE type='OUT' AND cost_amount IS NULL AND unit_price_snapshot IS NOT NULL;
    UPDATE ppe_transactions SET employee_code_snapshot=COALESCE(employee_code_snapshot,(SELECT e.employee_code FROM employees e WHERE e.id=ppe_transactions.employee_id)),
      employee_name_snapshot=COALESCE(employee_name_snapshot,(SELECT e.full_name FROM employees e WHERE e.id=ppe_transactions.employee_id)),
      department_snapshot=COALESCE(department_snapshot,(SELECT e.department FROM employees e WHERE e.id=ppe_transactions.employee_id)),
      site_snapshot=COALESCE(site_snapshot,(SELECT s.code FROM employees e LEFT JOIN sites s ON s.id=e.site_id WHERE e.id=ppe_transactions.employee_id)),
      snapshot_source=COALESCE(snapshot_source,'BACKFILL_CURRENT_REFERENCE')
      WHERE type='OUT';
  `);
  db.exec("UPDATE tasks SET status='not_started' WHERE status='open'; UPDATE tasks SET status='completed',progress=100,completed_at=COALESCE(completed_at,updated_at) WHERE status='done'; UPDATE obligations SET source_scope='legal_extra' WHERE id IN ('obl_env_report','obl_pc04_dec');");
