function loginGuard(username){
  const key=String(username||'').trim().toLowerCase();if(!key)return {key,locked:false};
  const row=db.prepare('SELECT * FROM login_guards WHERE username=?').get(key);if(!row)return {key,locked:false};
  const locked=!!row.locked_until&&new Date(row.locked_until)>new Date();return {key,locked,row};
}
function loginFailure(username){
  const key=String(username||'').trim().toLowerCase(),t=Date.now(),row=db.prepare('SELECT * FROM login_guards WHERE username=?').get(key);let count=1,first=new Date(t).toISOString();
  if(row&&row.first_failed_at&&t-new Date(row.first_failed_at).getTime()<=15*60_000){count=Number(row.failed_count||0)+1;first=row.first_failed_at}
  const lockedUntil=count>=5?new Date(t+15*60_000).toISOString():null;
  db.prepare(`INSERT INTO login_guards(username,failed_count,first_failed_at,last_failed_at,locked_until) VALUES(?,?,?,?,?) ON CONFLICT(username) DO UPDATE SET failed_count=excluded.failed_count,first_failed_at=excluded.first_failed_at,last_failed_at=excluded.last_failed_at,locked_until=excluded.locked_until`).run(key,count,first,new Date(t).toISOString(),lockedUntil);
  return {count,locked_until:lockedUntil};
}
function clearLoginGuard(username){db.prepare('DELETE FROM login_guards WHERE username=?').run(String(username||'').trim().toLowerCase())}
function isoMinusDays(dateStr,days){if(!dateStr)return null;const d=new Date(dateStr+'T12:00:00Z');d.setUTCDate(d.getUTCDate()-Number(days||0));return d.toISOString().slice(0,10)}
function ensureEquipmentReminder(eq){
  if(!eq?.next_inspection_date)return;const due=isoMinusDays(eq.next_inspection_date,eq.inspection_reminder_days??30),taskId=`task_inspection_${eq.id}`;
  db.prepare(`INSERT INTO tasks(id,title,category,site_id,owner,due_date,recurrence,priority,status,linked_entity_type,linked_entity_id,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET title=excluded.title,site_id=excluded.site_id,due_date=excluded.due_date,status='open',updated_at=excluded.updated_at`).run(taskId,`Chuẩn bị kiểm định ${eq.asset_code} - ${eq.name}`,'equipment',eq.site_id||null,'EHS',due,null,'high','open','equipment',eq.id,now(),now());
}


function legalBodyHash(text){const stable=String(text||'').replace(/<script[\s\S]*?<\/script>/gi,' ').replace(/<style[\s\S]*?<\/style>/gi,' ').replace(/<!--[\s\S]*?-->/g,' ').replace(/\s+/g,' ').trim();return crypto.createHash('sha256').update(stable).digest('hex')}
async function runLegalWatch({sourceIds=null,triggeredBy='system',fetchImpl=fetch}={}){
  const runId=id('lwr'),started=now();db.prepare(`INSERT INTO legal_watch_runs(id,started_at,status,triggered_by) VALUES(?,?,?,?)`).run(runId,started,'running',triggeredBy);
  const all=db.prepare(`SELECT * FROM legal_sources WHERE status='active' ORDER BY code`).all().filter(x=>!sourceIds||sourceIds.includes(x.id));let checked=0,changed=0,errors=0;const details=[];
  for(const src of all){checked++;try{const ctrl=new AbortController(),timer=setTimeout(()=>ctrl.abort(),8000);let r;try{r=await fetchImpl(src.official_url,{headers:{'User-Agent':'GAMI-EHS-LegalWatch/0.5','Accept':'text/html,application/xhtml+xml,application/pdf;q=0.8,*/*;q=0.5',...(src.etag?{'If-None-Match':src.etag}:{}),...(src.last_modified?{'If-Modified-Since':src.last_modified}:{})},signal:ctrl.signal,redirect:'follow'})}finally{clearTimeout(timer)}
      if(r.status===304){db.prepare('UPDATE legal_sources SET last_checked_at=?,last_http_status=?,last_error=NULL WHERE id=?').run(now(),304,src.id);details.push({id:src.id,code:src.code,status:'not_modified'});continue}
      if(!r.ok)throw new Error(`HTTP ${r.status}`);const text=await r.text(),h=legalBodyHash(text),isChange=!!src.content_hash&&src.content_hash!==h;
      db.prepare('UPDATE legal_sources SET content_hash=?,last_checked_at=?,last_http_status=?,last_error=NULL,etag=?,last_modified=?,verified_at=?,updated_at=? WHERE id=?').run(h,now(),r.status,r.headers.get('etag'),r.headers.get('last-modified'),now(),now(),src.id);
      if(isChange){changed++;const uid=id('lu');db.prepare(`INSERT INTO legal_updates(id,source_id,event_type,summary,impact_level,status,detected_at,analysis_note) VALUES(?,?,?,?,?,'needs_review',?,?)`).run(uid,src.id,'content_changed',`Nguồn chính thức ${src.code} có thay đổi nội dung/phiên bản so với lần kiểm tra trước.`,'high',now(),'Phát hiện bằng content hash. Bắt buộc EHS Legal Review trước khi thay đổi obligation.');audit('legal_watch.change_detected','legal_source',src.id,{legal_update_id:uid,old_hash:src.content_hash,new_hash:h},triggeredBy)}
      details.push({id:src.id,code:src.code,status:isChange?'changed':'baseline_or_same'});
    }catch(e){errors++;db.prepare('UPDATE legal_sources SET last_checked_at=?,last_error=?,updated_at=? WHERE id=?').run(now(),String(e.message||e),now(),src.id);details.push({id:src.id,code:src.code,status:'error',error:String(e.message||e)})}
  }
  const status=errors===checked&&checked?'failed':errors?'partial':'success';db.prepare('UPDATE legal_watch_runs SET finished_at=?,status=?,checked_count=?,changed_count=?,error_count=?,details_json=? WHERE id=?').run(now(),status,checked,changed,errors,JSON.stringify(details),runId);audit('legal_watch.run','system',runId,{status,checked,changed,errors},triggeredBy);return {id:runId,status,checked_count:checked,changed_count:changed,error_count:errors,details};
}
function upsertNotification(sourceType,sourceId,eventKey,title,message,level='info',targetRole='ehs_staff',dueDate=null){const nid=`ntf_${crypto.createHash('sha1').update(`${sourceType}|${sourceId}|${eventKey}`).digest('hex').slice(0,24)}`;db.prepare(`INSERT INTO notifications(id,source_type,source_id,event_key,title,message,level,target_role,status,due_date,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(source_type,source_id,event_key) DO UPDATE SET title=excluded.title,message=excluded.message,level=excluded.level,target_role=excluded.target_role,due_date=excluded.due_date,updated_at=excluded.updated_at`).run(nid,sourceType,sourceId,eventKey,title,message,level,targetRole,'unread',dueDate,now(),now());return nid}
function refreshNotifications(){const today=new Date().toISOString().slice(0,10),plus7=new Date(Date.now()+7*86400000).toISOString().slice(0,10),plus30=new Date(Date.now()+30*86400000).toISOString().slice(0,10);let n=0;const active=new Set();const add=(...args)=>{const nid=upsertNotification(...args);active.add(nid);n++;return nid};
  for(const o of db.prepare(`SELECT * FROM obligations WHERE status NOT IN ('done','closed') AND current_due_date IS NOT NULL`).all()){if(o.current_due_date<today)add('obligation',o.id,'overdue',`Quá hạn: ${o.title}`,`Deadline ${o.current_due_date} đã quá hạn.`,'critical','ehs_manager',o.current_due_date);else if(o.current_due_date<=plus7)add('obligation',o.id,'due_7',`Sắp hạn: ${o.title}`,`Còn ≤7 ngày tới deadline ${o.current_due_date}.`,'warning','ehs_staff',o.current_due_date)}
  for(const e of db.prepare(`SELECT * FROM equipment WHERE status='active' AND next_inspection_date IS NOT NULL`).all()){if(e.next_inspection_date<today)add('equipment',e.id,'inspection_expired',`Hết hạn kiểm định: ${e.asset_code}`,`${e.name} hết hạn ${e.next_inspection_date}.`,'critical','ehs_manager',e.next_inspection_date);else if(e.next_inspection_date<=plus30)add('equipment',e.id,'inspection_due_30',`Sắp kiểm định: ${e.asset_code}`,`${e.name} đến hạn ${e.next_inspection_date}.`,'warning','ehs_staff',e.next_inspection_date)}
  for(const p of db.prepare(`SELECT * FROM payments WHERE status NOT IN ('paid','archived') AND contractual_due_date IS NOT NULL`).all()){if(p.contractual_due_date<today)add('payment',p.id,'contract_overdue',`Thanh toán quá hạn hợp đồng: ${p.title}`,`Contract due ${p.contractual_due_date}; đây là cảnh báo tracking, không phải công nợ kế toán.`,'critical','ehs_manager',p.contractual_due_date)}
  for(const t of db.prepare(`SELECT * FROM tasks WHERE status='open' AND due_date IS NOT NULL AND due_date<?`).all(today))add('task',t.id,'task_overdue',`Task quá hạn: ${t.title}`,`Due ${t.due_date}.`,'warning','ehs_staff',t.due_date);
  for(const u of db.prepare(`SELECT u.*,s.code FROM legal_updates u JOIN legal_sources s ON s.id=u.source_id WHERE u.status='needs_review'`).all())add('legal_update',u.id,'legal_review',`Legal review: ${u.code}`,u.summary,u.impact_level==='high'?'critical':'warning','ehs_manager',null);
  const autoTypes=['obligation','equipment','payment','task','legal_update'];for(const row of db.prepare(`SELECT id,source_type,status FROM notifications WHERE source_type IN (${autoTypes.map(()=>'?').join(',')}) AND status<>'dismissed'`).all(...autoTypes)){if(!active.has(row.id))db.prepare("UPDATE notifications SET status='dismissed',updated_at=? WHERE id=?").run(now(),row.id)}
  return n}


