function paymentChecklist(category,amount){const rule=PAYMENT_CHECKLIST_RULES[category]||PAYMENT_CHECKLIST_RULES.other;return rule.docs.map(d=>({doc_type:d.doc_type,required:d.required==='amount_gt_5m'?Number(amount||0)>5000000:!!d.required,note:d.note||null}))}
function markLinkedTaskDeadlineChange(entityType,entityId,newDue){db.prepare(`UPDATE tasks SET source_due_date=?,deadline_sync_state=CASE WHEN due_date IS NULL OR due_date=? THEN 'synced' ELSE 'changed' END,due_date=CASE WHEN due_date IS NULL OR due_date=? THEN ? ELSE due_date END,updated_at=? WHERE linked_entity_type=? AND linked_entity_id=? AND status NOT IN ('completed','cancelled')`).run(newDue,newDue,newDue,newDue,now(),entityType,entityId)}
function obligationStatusDerived(o){if(o.status==='completed')return 'completed';if(o.current_due_date&&o.current_due_date<new Date().toISOString().slice(0,10))return 'overdue';return o.status}

function seedAuth(){
  db.prepare("DELETE FROM sessions WHERE datetime(expires_at)<=datetime('now')").run();

  // CP7.3: EHS_ADMIN_PASSWORD is the canonical Railway/cloud admin secret.
  // Keeping it in Railway Variables makes admin recovery deterministic across redeploys.
  // Legacy variables are still accepted for backwards compatibility.
  const configuredRaw=process.env.EHS_ADMIN_PASSWORD || process.env.EHS_RESET_ADMIN_PASSWORD || process.env.EHS_BOOTSTRAP_PASSWORD || '';
  const configured=String(configuredRaw);
  if(configured && configured.length<10){
    throw new Error('EHS_ADMIN_PASSWORD / reset / bootstrap password must be at least 10 characters');
  }

  let existing=db.prepare("SELECT * FROM users WHERE lower(username)='admin' ORDER BY created_at LIMIT 1").get();
  if(!existing){
    const password=configured || `Ehs-${crypto.randomBytes(9).toString('base64url')}!`;
    const h=hashPassword(password);
    db.prepare(`INSERT INTO users(id,username,display_name,role,password_salt,password_hash,active,must_change_password,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?)`).run('usr_admin','admin','EHS Administrator','admin',h.salt,h.hash,1,configured?0:1,now(),now());
    clearLoginGuard('admin');
    console.log('\n=== VIETCHEM EHS FIRST RUN ===\nUsername: admin\n'+(configured?'Admin password loaded from Railway/environment variable EHS_ADMIN_PASSWORD.':'Temporary password: '+password)+'\n===============================\n');
    existing=db.prepare("SELECT * FROM users WHERE lower(username)='admin' ORDER BY created_at LIMIT 1").get();
  }

  if(existing && configured){
    const h=hashPassword(configured);
    db.prepare("UPDATE users SET username='admin',role='admin',password_salt=?,password_hash=?,must_change_password=0,active=1,updated_at=? WHERE id=?").run(h.salt,h.hash,now(),existing.id);
    clearLoginGuard('admin');
    db.prepare('DELETE FROM sessions WHERE user_id=?').run(existing.id);
    console.log('[AUTH] Admin credential synchronized from EHS_ADMIN_PASSWORD/environment and login lock cleared.');
  }
}

function parseDateOnly(str){if(!/^\d{4}-\d{2}-\d{2}$/.test(String(str||'')))return null;const [y,m,d]=str.split('-').map(Number);return {y,m,d}}
function formatDateOnly(y,m,d){return `${String(y).padStart(4,'0')}-${String(m).padStart(2,'0')}-${String(d).padStart(2,'0')}`}
function daysInMonth(y,m){return new Date(Date.UTC(y,m,0)).getUTCDate()}
function nextRecurringDate(dateStr,recurrence,interval=1){const p=parseDateOnly(dateStr);if(!p)return null;const n=Math.max(1,Math.min(365,Number(interval)||1));if(recurrence==='daily'||recurrence==='weekly'){const dt=new Date(Date.UTC(p.y,p.m-1,p.d));dt.setUTCDate(dt.getUTCDate()+(recurrence==='daily'?n:n*7));return formatDateOnly(dt.getUTCFullYear(),dt.getUTCMonth()+1,dt.getUTCDate())}if(recurrence==='monthly'){const base=(p.m-1)+n,ny=p.y+Math.floor(base/12),nm=(base%12+12)%12+1,nd=Math.min(p.d,daysInMonth(ny,nm));return formatDateOnly(ny,nm,nd)}return null}
function validRecurrence(x){return x==null||x===''||['daily','weekly','monthly'].includes(x)}
function recurrenceEvents(task,start,end){if(!task.recurrence||!task.due_date||['cancelled','completed'].includes(task.status))return [];const out=[];let d=task.due_date,guard=0;while(d<start&&guard++<1000){const n=nextRecurringDate(d,task.recurrence,task.recurrence_interval);if(!n||n===d)return out;d=n}while(d<=end&&guard++<2000){if(!task.recurrence_end_date||d<=task.recurrence_end_date)out.push(d);else break;const n=nextRecurringDate(d,task.recurrence,task.recurrence_interval);if(!n||n===d)break;d=n}return out}

function ensureHardeningSchema(){
  db.exec(`
    CREATE TABLE IF NOT EXISTS system_meta(key TEXT PRIMARY KEY,value TEXT,updated_at TEXT NOT NULL);
    CREATE TABLE IF NOT EXISTS upgrade_runs(
      id TEXT PRIMARY KEY,from_version TEXT,to_version TEXT NOT NULL,started_at TEXT NOT NULL,finished_at TEXT,status TEXT NOT NULL,
      backup_path TEXT,pre_counts_json TEXT,post_counts_json TEXT,migrations_json TEXT,error TEXT
    );
    CREATE TABLE IF NOT EXISTS backup_history(
      id TEXT PRIMARY KEY,kind TEXT NOT NULL,file_name TEXT NOT NULL,file_path TEXT NOT NULL,created_at TEXT NOT NULL,
      size_bytes INTEGER,manifest_created_at TEXT,valid INTEGER NOT NULL DEFAULT 1,note TEXT
    );
  `);
}

