function tableExistsSafe(name){return !!db.prepare("SELECT 1 FROM sqlite_master WHERE type='table' AND name=?").get(name)}
function metaGet(key){if(!tableExistsSafe('system_meta'))return null;return db.prepare('SELECT value FROM system_meta WHERE key=?').get(key)?.value??null}
function metaSet(key,value){db.prepare(`INSERT INTO system_meta(key,value,updated_at) VALUES(?,?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value,updated_at=excluded.updated_at`).run(key,String(value??''),now())}
function safeStamp(){return now().replace(/[:.]/g,'-')}
async function writeValidatedBackup(kind,prefix){
  const out=await createBackupArchive({db,dataDir:DATA_DIR,uploadDir:UPLOAD_DIR,appVersion:APP_VERSION});
  const check=validateBackupArchive(out.buffer);if(!check.ok)throw new Error(`BACKUP_VALIDATION_FAILED:${check.problems.join('; ')}`);
  const name=`${prefix}_${safeStamp()}.tar.gz`,path=join(BACKUP_DIR,name);await writeFile(path,out.buffer);
  if(tableExistsSafe('backup_history')) db.prepare(`INSERT INTO backup_history(id,kind,file_name,file_path,created_at,size_bytes,manifest_created_at,valid,note) VALUES(?,?,?,?,?,?,?,?,?)`).run(id('bkp'),kind,name,path,now(),out.buffer.length,out.manifest.created_at,1,null);
  return {path,name,size_bytes:out.buffer.length,manifest:out.manifest};
}
async function startupMigrate(){
  const started=now(),pre=snapshotCounts(db),fromVersion=metaGet('app_version')||(DB_EXISTED_AT_START?'legacy_cp5x_or_earlier':'fresh');
  let pending=[];try{pending=pendingMigrations(db,MIGRATIONS)}catch(e){throw e}
  let safety=null;
  const hasUserTables=Number(db.prepare("SELECT COUNT(*) c FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%'").get().c)>0;
  if(pending.length&&DB_EXISTED_AT_START&&hasUserTables){
    safety=await writeValidatedBackup('pre_migration','pre_migration');
    console.log(`[DATA SAFETY] Pre-migration backup: ${safety.path}`);
  }
  try{
    const result=runMigrations(db,MIGRATIONS,{appVersion:APP_VERSION});
    const post=snapshotCounts(db),cmp=compareCounts(pre,post);if(!cmp.ok)throw new Error(`DATA_COUNT_REGRESSION:${JSON.stringify(cmp.drops)}`);
    metaSet('app_version',APP_VERSION);metaSet('schema_version',result.latest||'none');metaSet('data_home',EHS_HOME_DIR);metaSet('data_dir',DATA_DIR);metaSet('upload_dir',UPLOAD_DIR);metaSet('last_startup_at',now());
    if(tableExistsSafe('upgrade_runs')) db.prepare(`INSERT INTO upgrade_runs(id,from_version,to_version,started_at,finished_at,status,backup_path,pre_counts_json,post_counts_json,migrations_json,error) VALUES(?,?,?,?,?,'success',?,?,?,?,NULL)`).run(id('upr'),fromVersion,APP_VERSION,started,now(),safety?.path||null,JSON.stringify(pre),JSON.stringify(post),JSON.stringify(result.applied));
    return {fromVersion,...result,backup:safety,pre,post};
  }catch(e){
    console.error('[DATA SAFETY] Migration failed:',e.message||e);
    if(safety){
      const bytes=await readFile(safety.path);db.close();await restoreBackupArchive(bytes,{dataDir:DATA_DIR,uploadDir:UPLOAD_DIR});
      console.error('[DATA SAFETY] Previous database/uploads restored from validated pre-migration backup. Restart the old version or fix the update before retrying.');
    }
    throw e;
  }
}
async function maybeAutoBackup(){
  if(!AUTO_BACKUP_ENABLED)return null;
  let files=[];try{files=(await readdir(BACKUP_DIR)).filter(x=>/^auto_.*\.tar\.gz$/i.test(x))}catch{return null}
  let newest=0;for(const f of files){try{newest=Math.max(newest,(await stat(join(BACKUP_DIR,f))).mtimeMs)}catch{}}
  if(newest&&Date.now()-newest<24*3600_000)return null;
  const out=await writeValidatedBackup('auto','auto');metaSet('last_auto_backup_at',now());
  const cutoff=Date.now()-AUTO_BACKUP_RETENTION_DAYS*86400_000;
  for(const f of files){try{const p=join(BACKUP_DIR,f),st=await stat(p);if(st.mtimeMs<cutoff)await rm(p,{force:true})}catch{}}
  console.log(`[BACKUP] Daily automatic backup: ${out.path}`);return out;
}

