const routes=[]; function route(method,pathname,handler){routes.push({method,pathname,handler})}
route('POST','/api/auth/login',async(req,res)=>{const b=await bodyJson(req),username=String(b.username||'').trim();const u=db.prepare('SELECT * FROM users WHERE lower(username)=lower(?) AND active=1').get(username);const passwordOk=!!u&&verifyPassword(b.password||'',u.password_salt,u.password_hash);if(passwordOk){clearLoginGuard(username);const token=crypto.randomBytes(32).toString('base64url'),expires=new Date(Date.now()+8*3600_000).toISOString();db.prepare('INSERT INTO sessions(token_hash,user_id,expires_at,created_at) VALUES(?,?,?,?)').run(tokenHash(token),u.id,expires,now());audit('auth.login','user',u.id,{role:u.role},u.username);return json(res,200,{user:{id:u.id,username:u.username,display_name:u.display_name,role:u.role,must_change_password:!!u.must_change_password}}, {'Set-Cookie':sessionCookie(token)})}const guard=loginGuard(username);if(guard.locked){audit('auth.login_blocked','user',u?.id||null,{username,locked_until:guard.row.locked_until},username||'unknown');return json(res,429,{error:'LOGIN_LOCKED',locked_until:guard.row.locked_until})}const fail=loginFailure(username);audit('auth.login_failed','user',u?.id||null,{username,failed_count:fail.count,locked_until:fail.locked_until},username||'unknown');return json(res,401,{error:'Sai tài khoản hoặc mật khẩu'})});
route('GET','/api/auth/me',async(req,res)=>json(res,200,{user:req.user,permissions:ROLE_PERMS[req.user.role]||[]}));
route('POST','/api/auth/logout',async(req,res)=>{const token=parseCookies(req).ehs_session;if(token)db.prepare('DELETE FROM sessions WHERE token_hash=?').run(tokenHash(token));audit('auth.logout','user',req.user.id,{},req.user.username);json(res,200,{ok:true},{'Set-Cookie':sessionCookie('',0)})});
route('POST','/api/auth/change-password',async(req,res)=>{const b=await bodyJson(req);const u=db.prepare('SELECT * FROM users WHERE id=?').get(req.user.id);if(!verifyPassword(b.old_password||'',u.password_salt,u.password_hash))return json(res,400,{error:'Mật khẩu hiện tại không đúng'});if(String(b.new_password||'').length<10)return json(res,400,{error:'Mật khẩu mới tối thiểu 10 ký tự'});const h=hashPassword(b.new_password);db.prepare('UPDATE users SET password_salt=?,password_hash=?,must_change_password=0,updated_at=? WHERE id=?').run(h.salt,h.hash,now(),u.id);db.prepare('DELETE FROM sessions WHERE user_id=? AND token_hash<>?').run(u.id,tokenHash(parseCookies(req).ehs_session||''));audit('auth.password_changed','user',u.id,{},u.username);json(res,200,{ok:true})});
route('GET','/api/users',async(req,res)=>json(res,200,db.prepare('SELECT id,username,display_name,role,active,must_change_password,created_at,updated_at FROM users ORDER BY active DESC,display_name').all()));
route('POST','/api/users',async(req,res)=>{const b=await bodyJson(req);if(!b.username||!b.display_name||!ROLE_PERMS[b.role]||String(b.password||'').length<10)return json(res,400,{error:'username, display_name, role và mật khẩu >=10 ký tự là bắt buộc'});const h=hashPassword(b.password),uid=id('usr');try{db.prepare(`INSERT INTO users(id,username,display_name,role,password_salt,password_hash,active,must_change_password,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?)`).run(uid,String(b.username).trim(),b.display_name,b.role,h.salt,h.hash,1,1,now(),now());audit('user.created','user',uid,{username:b.username,role:b.role},actor(req));json(res,201,{id:uid})}catch(e){json(res,400,{error:String(e.message).includes('UNIQUE')?'Username đã tồn tại':e.message})}});
route('PATCH','/api/users',async(req,res)=>{const b=await bodyJson(req);if(!b.id)return json(res,400,{error:'id required'});if(b.role&&!ROLE_PERMS[b.role])return json(res,400,{error:'invalid role'});db.prepare('UPDATE users SET role=COALESCE(?,role),active=COALESCE(?,active),updated_at=? WHERE id=?').run(b.role||null,b.active==null?null:(b.active?1:0),now(),b.id);audit('user.updated','user',b.id,{role:b.role,active:b.active},actor(req));json(res,200,{ok:true})});
route('GET','/api/admin/backup',async(req,res)=>{try{const out=await createBackupArchive({db,dataDir:DATA_DIR,uploadDir:UPLOAD_DIR,appVersion:APP_VERSION});const check=validateBackupArchive(out.buffer);if(!check.ok)throw new Error(`BACKUP_VALIDATION_FAILED:${check.problems.join('; ')}`);const stamp=safeStamp(),fileName=`manual_${stamp}.tar.gz`,serverPath=join(BACKUP_DIR,fileName);await writeFile(serverPath,out.buffer);if(tableExistsSafe('backup_history'))db.prepare(`INSERT INTO backup_history(id,kind,file_name,file_path,created_at,size_bytes,manifest_created_at,valid,note) VALUES(?,?,?,?,?,?,?,?,?)`).run(id('bkp'),'manual',fileName,serverPath,now(),out.buffer.length,out.manifest.created_at,1,'Created from System UI/API and also downloaded to browser');audit('system.backup_created','system','backup',{files:out.manifest.files.length,size_bytes:out.buffer.length,server_path:serverPath},actor(req));res.writeHead(200,securityHeaders({'Content-Type':'application/gzip','Content-Length':out.buffer.length,'Content-Disposition':`attachment; filename=VIETCHEM_EHS_backup_${stamp}.tar.gz`,'Cache-Control':'no-store','X-EHS-Backup-Saved':'1'}));res.end(out.buffer)}catch(e){json(res,500,{error:e.message})}});
route('POST','/api/admin/backup/validate',async(req,res)=>{const b=await bodyJson(req);if(!b.base64)return json(res,400,{error:'base64 backup required'});const bytes=Buffer.from(b.base64,'base64');if(bytes.length>250*1024*1024)return json(res,413,{error:'backup too large'});try{const out=validateBackupArchive(bytes);audit('system.backup_validated','system','backup',{ok:out.ok,problems:out.problems,created_at:out.manifest?.created_at},actor(req));json(res,out.ok?200:400,{ok:out.ok,problems:out.problems,manifest:out.manifest})}catch(e){json(res,400,{ok:false,error:e.message})}});


route('GET','/api/export/excel',async(req,res,url)=>{
  const scope=(url.searchParams.get('scope')||'all').toLowerCase();const perm=exportScopePermission(scope);if(!perm)return json(res,400,{error:'INVALID_EXPORT_SCOPE'});if(scope==='all'&&!hasPerm(req.user,'compliance.read'))return json(res,403,{error:'FORBIDDEN',permission:'compliance.read'});if(scope!=='all'&&!hasPerm(req.user,perm))return json(res,403,{error:'FORBIDDEN',permission:perm});
  const filters=Object.fromEntries(url.searchParams.entries());delete filters.scope;const sheets=buildExportSheets(scope,req.user,filters);if(!sheets.length)return json(res,403,{error:'NO_EXPORTABLE_DATA_FOR_ROLE'});const out=buildXlsx(sheets);const stamp=new Date().toISOString().slice(0,10).replaceAll('-','');const name=`VIETCHEM_EHS_${scope}_${stamp}.xlsx`;audit('excel.exported','system',scope,{scope,sheets:sheets.map(x=>x.name),bytes:out.length},actor(req));res.writeHead(200,securityHeaders({'Content-Type':'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','Content-Length':out.length,'Content-Disposition':`attachment; filename="${name}"`,'Cache-Control':'no-store'}));res.end(out);
});

route('GET','/api/search',async(req,res,url)=>{const q=String(url.searchParams.get('q')||'').trim();if(q.length<2)return json(res,200,{query:q,results:[]});const like=`%${q}%`,results=[];const push=(type,view,rows,title,subtitle)=>rows.forEach(r=>results.push({type,view,id:r.id,title:title(r),subtitle:subtitle(r)}));
  if(hasPerm(req.user,'employees.read'))push('employee','employees',db.prepare(`SELECT e.*,s.code site_code FROM employees e LEFT JOIN sites s ON s.id=e.site_id WHERE e.full_name LIKE ? OR COALESCE(e.employee_code,'') LIKE ? OR COALESCE(e.department,'') LIKE ? LIMIT 8`).all(like,like,like),r=>r.full_name,r=>`${r.employee_code||'—'} · ${r.department||'—'} · ${r.site_code||'—'}`);
  if(hasPerm(req.user,'ppe.read'))push('ppe','ppe',db.prepare(`SELECT * FROM ppe_items WHERE name LIKE ? OR sku LIKE ? LIMIT 8`).all(like,like),r=>`${r.sku} · ${r.name}`,r=>`Tồn ${r.current_stock} ${r.unit||''}`);
  if(hasPerm(req.user,'compliance.read'))push('compliance','compliance',db.prepare(`SELECT o.*,s.code site_code FROM obligations o LEFT JOIN sites s ON s.id=o.site_id WHERE o.title LIKE ? OR COALESCE(o.legal_basis,'') LIKE ? OR COALESCE(o.owner,'') LIKE ? LIMIT 10`).all(like,like,like),r=>r.title,r=>`${r.site_code||'—'} · ${r.owner||'—'} · ${r.current_due_date||'không deadline'}`);
  if(hasPerm(req.user,'compliance.read'))push('legal','compliance',db.prepare(`SELECT id,code,title,category,issuer,effective_date FROM legal_sources WHERE code LIKE ? OR title LIKE ? OR COALESCE(issuer,'') LIKE ? LIMIT 10`).all(like,like,like),r=>`${r.code} · ${r.title}`,r=>`${r.category||'—'} · ${r.issuer||'—'} · hiệu lực ${r.effective_date||'—'}`);
  if(hasPerm(req.user,'documents.read'))push('document','documents',db.prepare(`SELECT d.*,s.code site_code FROM documents d LEFT JOIN sites s ON s.id=d.site_id WHERE d.original_name LIKE ? OR COALESCE(d.document_no,'') LIKE ? OR COALESCE(d.tags,'') LIKE ? LIMIT 10`).all(like,like,like),r=>r.original_name,r=>`${r.category||'other'} / ${r.subcategory||'—'} · ${r.document_no||'—'} · ${r.site_code||'—'}`);
  if(hasPerm(req.user,'payments.read'))push('payment','payments',db.prepare(`SELECT p.*,v.name vendor_name FROM payments p JOIN vendors v ON v.id=p.vendor_id WHERE p.title LIKE ? OR COALESCE(p.invoice_no,'') LIKE ? OR v.name LIKE ? LIMIT 8`).all(like,like,like),r=>r.title,r=>`${r.vendor_name} · HĐ ${r.invoice_no||'—'} · ${r.amount||0} VND`);
  if(hasPerm(req.user,'equipment.read'))push('equipment','equipment',db.prepare(`SELECT e.*,s.code site_code FROM equipment e LEFT JOIN sites s ON s.id=e.site_id WHERE e.asset_code LIKE ? OR e.name LIKE ? OR COALESCE(e.serial_no,'') LIKE ? OR COALESCE(e.location,'') LIKE ? LIMIT 10`).all(like,like,like,like),r=>`${r.asset_code} · ${r.name}`,r=>`${r.serial_no||'—'} · ${r.site_code||'—'} · ${r.location||'—'}`);
  if(hasPerm(req.user,'tasks.read'))push('task','tasks',db.prepare(`SELECT t.*,s.code site_code FROM tasks t LEFT JOIN sites s ON s.id=t.site_id WHERE t.title LIKE ? OR COALESCE(t.notes,'') LIKE ? OR COALESCE(t.owner,'') LIKE ? LIMIT 10`).all(like,like,like),r=>r.title,r=>`${r.site_code||'—'} · ${r.owner||'—'} · ${r.status}`);
  json(res,200,{query:q,results:results.slice(0,60)});
});
