const PPE_UNALLOCATED_SIZE='__UNALLOCATED__';
function normalizePpeSizes(value){
  let arr=[];
  if(Array.isArray(value)) arr=value;
  else if(typeof value==='string'&&value.trim()){
    try{const j=JSON.parse(value);arr=Array.isArray(j)?j:value.split(/[,;\n]+/)}catch{arr=value.split(/[,;\n]+/)}
  }
  const seen=new Set(),out=[];
  for(const raw of arr){const x=String(raw??'').trim();if(!x||x===PPE_UNALLOCATED_SIZE)continue;const k=x.toLowerCase();if(seen.has(k))continue;seen.add(k);out.push(x)}
  return out.slice(0,40);
}
function ppeSizeOptionsFromItem(p){return normalizePpeSizes(p?.size_options_json||'')}
function ppeSizeStocks(itemId){return db.prepare(`SELECT item_id,size_label,current_stock,min_stock,active,updated_at FROM ppe_size_stocks WHERE item_id=? ORDER BY CASE WHEN size_label=? THEN 1 ELSE 0 END, size_label`).all(itemId,PPE_UNALLOCATED_SIZE)}
function enrichPpeItem(p){return {...p,one_size:Number(p.one_size??1),size_options:ppeSizeOptionsFromItem(p),size_stocks:ppeSizeStocks(p.id)}}
function initializeMultiSizeStock(itemId,totalStock,options){
  db.prepare('DELETE FROM ppe_size_stocks WHERE item_id=?').run(itemId);
  const ins=db.prepare(`INSERT INTO ppe_size_stocks(item_id,size_label,current_stock,min_stock,active,updated_at) VALUES(?,?,?,?,?,?)`);
  for(const label of options)ins.run(itemId,label,0,0,1,now());
  ins.run(itemId,PPE_UNALLOCATED_SIZE,Number(totalStock||0),0,1,now());
}
function syncMultiSizeOptions(itemId,options){
  db.prepare(`UPDATE ppe_size_stocks SET active=CASE WHEN size_label=? THEN 1 ELSE 0 END,updated_at=? WHERE item_id=?`).run(PPE_UNALLOCATED_SIZE,now(),itemId);
  const up=db.prepare(`INSERT INTO ppe_size_stocks(item_id,size_label,current_stock,min_stock,active,updated_at) VALUES(?,?,0,0,1,?) ON CONFLICT(item_id,size_label) DO UPDATE SET active=1,updated_at=excluded.updated_at`);
  for(const label of options)up.run(itemId,label,now());
  const total=Number(db.prepare('SELECT current_stock FROM ppe_items WHERE id=?').get(itemId)?.current_stock||0);
  const sum=Number(db.prepare(`SELECT COALESCE(SUM(current_stock),0) v FROM ppe_size_stocks WHERE item_id=? AND size_label<>?`).get(itemId,PPE_UNALLOCATED_SIZE).v||0);
  db.prepare(`INSERT INTO ppe_size_stocks(item_id,size_label,current_stock,min_stock,active,updated_at) VALUES(?,?,?,?,1,?) ON CONFLICT(item_id,size_label) DO UPDATE SET current_stock=excluded.current_stock,active=1,updated_at=excluded.updated_at`).run(itemId,PPE_UNALLOCATED_SIZE,total-sum,0,now());
}
function ppeOperationalSizeRow(itemId,sizeLabel){return db.prepare(`SELECT * FROM ppe_size_stocks WHERE item_id=? AND size_label=? AND (active=1 OR size_label=?)`).get(itemId,sizeLabel,PPE_UNALLOCATED_SIZE)}

route('GET','/api/ppe/catalog',async(_req,res)=>{const rows=db.prepare(`SELECT p.*,(SELECT COUNT(*) FROM ppe_transactions t WHERE t.item_id=p.id) tx_count FROM ppe_items p ORDER BY p.active DESC,p.name`).all().map(enrichPpeItem);json(res,200,rows)});
route('POST','/api/ppe/catalog',async(req,res)=>{const b=await bodyJson(req);const sku=String(b.sku||'').trim(),name=String(b.name||'').trim(),unit=String(b.unit||'cái').trim()||'cái';if(!sku||!name)return json(res,400,{error:'SKU và tên PPE là bắt buộc'});const minStock=Number(b.min_stock||0),life=b.lifecycle_days==null||b.lifecycle_days===''?null:Number(b.lifecycle_days),price=b.unit_price==null||b.unit_price===''?null:Number(b.unit_price),opening=Number(b.opening_stock||0),oneSize=b.one_size===undefined?1:(b.one_size?1:0),sizes=normalizePpeSizes(b.size_options);if(!Number.isFinite(minStock)||minStock<0)return json(res,400,{error:'min_stock phải >=0'});if(life!==null&&(!Number.isFinite(life)||life<0))return json(res,400,{error:'lifecycle_days không hợp lệ'});if(price!==null&&(!Number.isFinite(price)||price<0))return json(res,400,{error:'unit_price phải >=0'});if(!Number.isFinite(opening))return json(res,400,{error:'opening_stock không hợp lệ'});if(!oneSize&&!sizes.length)return json(res,400,{error:'PPE nhiều size phải khai báo ít nhất 1 size'});const pid=id('ppe');db.exec('BEGIN IMMEDIATE');try{db.prepare(`INSERT INTO ppe_items(id,sku,name,unit,size_variant,min_stock,lifecycle_days,current_stock,active,created_at,unit_price,updated_at,one_size,size_options_json) VALUES(?,?,?,?,?,?,?,?,1,?,?,?,?,?)`).run(pid,sku,name,unit,String(b.size_variant||'').trim()||null,minStock,life,opening,now(),price,now(),oneSize,oneSize?null:JSON.stringify(sizes));if(!oneSize)initializeMultiSizeStock(pid,opening,sizes);if(opening!==0){const sizeLabel=oneSize?null:PPE_UNALLOCATED_SIZE;db.prepare(`INSERT INTO ppe_transactions(id,item_id,type,quantity,stock_before,stock_after,reason,note,actor,created_at,unit_price_snapshot,cost_amount,snapshot_source,size_label,size_stock_before,size_stock_after) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).run(id('ptx'),pid,'OPENING_IMPORT',Math.abs(opening),0,opening,'Tồn đầu kỳ khi tạo loại PPE',b.note||null,actor(req,'EHS'),now(),price,price==null?null:Math.abs(opening)*price,'CATALOG_CREATE',sizeLabel,sizeLabel?0:null,sizeLabel?opening:null)}audit('ppe.catalog_created','ppe_item',pid,{sku,name,unit,opening_stock:opening,min_stock:minStock,unit_price:price,one_size:!!oneSize,size_options:sizes},actor(req,'EHS'));db.exec('COMMIT');json(res,201,{id:pid})}catch(e){db.exec('ROLLBACK');json(res,400,{error:String(e.message).includes('UNIQUE')?'SKU đã tồn tại':e.message})}});
route('PATCH','/api/ppe/catalog',async(req,res)=>{const b=await bodyJson(req);if(!b.id)return json(res,400,{error:'id required'});const old=db.prepare('SELECT * FROM ppe_items WHERE id=?').get(b.id);if(!old)return json(res,404,{error:'PPE item not found'});const active=b.active==null?Number(old.active):(b.active?1:0),reason=String(b.inactive_reason||'').trim();if(Number(old.active)===1&&active===0&&!reason)return json(res,400,{error:'Bắt buộc nhập lý do khi bỏ/ngừng loại PPE'});const sku=b.sku==null?old.sku:String(b.sku).trim(),name=b.name==null?old.name:String(b.name).trim(),unit=b.unit==null?old.unit:String(b.unit).trim();if(!sku||!name||!unit)return json(res,400,{error:'SKU, tên PPE và ĐVT không được trống'});const size=b.size_variant===undefined?old.size_variant:(String(b.size_variant||'').trim()||null),minStock=b.min_stock===undefined?Number(old.min_stock):Number(b.min_stock),life=b.lifecycle_days===undefined?old.lifecycle_days:(b.lifecycle_days===''||b.lifecycle_days==null?null:Number(b.lifecycle_days)),price=b.unit_price===undefined?old.unit_price:(b.unit_price===''||b.unit_price==null?null:Number(b.unit_price)),oneSize=b.one_size===undefined?Number(old.one_size??1):(b.one_size?1:0),sizes=b.size_options===undefined?ppeSizeOptionsFromItem(old):normalizePpeSizes(b.size_options);if(!Number.isFinite(minStock)||minStock<0)return json(res,400,{error:'min_stock phải >=0'});if(life!==null&&(!Number.isFinite(Number(life))||Number(life)<0))return json(res,400,{error:'lifecycle_days không hợp lệ'});if(price!==null&&(!Number.isFinite(Number(price))||Number(price)<0))return json(res,400,{error:'unit_price phải >=0'});if(!oneSize&&!sizes.length)return json(res,400,{error:'PPE nhiều size phải khai báo ít nhất 1 size'});const oldOne=Number(old.one_size??1);if(oldOne===0){const existingRows=ppeSizeStocks(old.id);if(oneSize===1){const nonzero=existingRows.filter(x=>x.size_label!==PPE_UNALLOCATED_SIZE&&Math.abs(Number(x.current_stock||0))>1e-9);if(nonzero.length)return json(res,400,{error:`Không thể chuyển sang Một size khi còn tồn theo size: ${nonzero.map(x=>`${x.size_label}=${x.current_stock}`).join(', ')}`})}else{const removed=ppeSizeOptionsFromItem(old).filter(x=>!sizes.includes(x));const blocked=removed.map(label=>existingRows.find(r=>r.size_label===label)).filter(r=>r&&Math.abs(Number(r.current_stock||0))>1e-9);if(blocked.length)return json(res,400,{error:`Không thể bỏ size còn tồn: ${blocked.map(x=>`${x.size_label}=${x.current_stock}`).join(', ')}`})}}db.exec('BEGIN IMMEDIATE');try{db.prepare(`UPDATE ppe_items SET sku=?,name=?,unit=?,size_variant=?,min_stock=?,lifecycle_days=?,unit_price=?,active=?,inactive_reason=?,updated_at=?,one_size=?,size_options_json=? WHERE id=?`).run(sku,name,unit,size,minStock,life,price,active,active?null:(reason||old.inactive_reason),now(),oneSize,oneSize?null:JSON.stringify(sizes),old.id);if(oldOne===1&&oneSize===0)initializeMultiSizeStock(old.id,old.current_stock,sizes);else if(oldOne===0&&oneSize===0)syncMultiSizeOptions(old.id,sizes);else if(oneSize===1)db.prepare('UPDATE ppe_size_stocks SET active=0,updated_at=? WHERE item_id=?').run(now(),old.id);audit(active!==Number(old.active)?(active?'ppe.catalog_reactivated':'ppe.catalog_deactivated'):'ppe.catalog_updated','ppe_item',old.id,{before:{sku:old.sku,name:old.name,unit:old.unit,size_variant:old.size_variant,min_stock:old.min_stock,lifecycle_days:old.lifecycle_days,unit_price:old.unit_price,active:old.active,one_size:oldOne,size_options:ppeSizeOptionsFromItem(old)},after:{sku,name,unit,size_variant:size,min_stock:minStock,lifecycle_days:life,unit_price:price,active,one_size:oneSize,size_options:sizes},inactive_reason:reason||null,current_stock:old.current_stock},actor(req,'EHS'));db.exec('COMMIT');json(res,200,{ok:true})}catch(e){db.exec('ROLLBACK');json(res,400,{error:String(e.message).includes('UNIQUE')?'SKU đã tồn tại':e.message})}});
route('GET','/api/ppe',async(_req,res)=>{const items=db.prepare('SELECT * FROM ppe_items WHERE active=1 ORDER BY name').all().map(enrichPpeItem);const tx=db.prepare(`SELECT t.*,p.name item_name,e.full_name employee_name FROM ppe_transactions t JOIN ppe_items p ON p.id=t.item_id LEFT JOIN employees e ON e.id=t.employee_id ORDER BY t.created_at DESC LIMIT 150`).all();json(res,200,{items,transactions:tx})});
route('GET','/api/ppe/history',async(_req,res,url)=>{const type=String(url.searchParams.get('type')||'').trim().toUpperCase(),q=String(url.searchParams.get('q')||'').trim().toLowerCase(),limit=Math.min(1000,Math.max(1,Number(url.searchParams.get('limit')||500)||500));let sql=`SELECT t.*,p.sku,p.name item_name,COALESCE(t.employee_code_snapshot,e.employee_code) employee_code,COALESCE(t.employee_name_snapshot,e.full_name) employee_name,COALESCE(t.department_snapshot,e.department) department FROM ppe_transactions t JOIN ppe_items p ON p.id=t.item_id LEFT JOIN employees e ON e.id=t.employee_id WHERE 1=1`;const args=[];if(type){sql+=' AND t.type=?';args.push(type)}if(q){sql+=` AND (lower(p.name) LIKE ? OR lower(p.sku) LIKE ? OR lower(COALESCE(t.employee_name_snapshot,e.full_name,'')) LIKE ? OR lower(COALESCE(t.department_snapshot,e.department,'')) LIKE ? OR lower(COALESCE(t.reason,'')) LIKE ? OR lower(COALESCE(t.note,'')) LIKE ? OR lower(COALESCE(t.size_label,'')) LIKE ? OR lower(COALESCE(t.correction_reason,'')) LIKE ?)`;const x=`%${q}%`;args.push(x,x,x,x,x,x,x,x)}sql+=' ORDER BY COALESCE(t.effective_at,t.created_at) DESC,t.created_at DESC LIMIT ?';args.push(limit);json(res,200,db.prepare(sql).all(...args))});
route('POST','/api/ppe/history/correct',async(req,res)=>{
  const b=await bodyJson(req),mode=String(b.mode||'correct').toLowerCase(),correctionReason=String(b.correction_reason||'').trim();
  if(!b.transaction_id||!['correct','cancel'].includes(mode)||!correctionReason)return json(res,400,{error:'transaction_id, mode và lý do chỉnh sửa là bắt buộc'});
  const original=db.prepare(`SELECT * FROM ppe_transactions WHERE id=?`).get(b.transaction_id);
  if(!original)return json(res,404,{error:'Giao dịch xuất không tồn tại'});
  if(original.type!=='OUT')return json(res,400,{error:'Chỉ cho phép sửa giao dịch Xuất PPE'});
  if(String(original.tx_status||'active')!=='active')return json(res,409,{error:'Giao dịch này đã được sửa/hoàn trước đó'});
  let newEmp=null,newItem=null,newQty=null,newSize=null;
  if(mode==='correct'){
    newQty=Number(b.quantity);if(!(newQty>0))return json(res,400,{error:'Số lượng mới phải >0'});
    newEmp=db.prepare("SELECT e.*,s.code site_code FROM employees e LEFT JOIN sites s ON s.id=e.site_id WHERE e.id=? AND e.status='active'").get(b.employee_id);
    if(!newEmp)return json(res,400,{error:'Người nhận mới không hợp lệ/đã inactive'});
    newItem=db.prepare('SELECT * FROM ppe_items WHERE id=? AND active=1').get(b.item_id);
    if(!newItem)return json(res,400,{error:'PPE mới không tồn tại/đã ngừng'});
    if(Number(newItem.one_size??1)!==1){newSize=String(b.size_label||'').trim();const allowed=ppeSizeOptionsFromItem(newItem);if(!newSize||!allowed.includes(newSize))return json(res,400,{error:`Vui lòng chọn size hợp lệ cho ${newItem.name}`})}
  }
  const who=actor(req,'EHS'),ts=now();
  db.exec('BEGIN IMMEDIATE');
  try{
    // 1) Hoàn nguyên giao dịch xuất cũ về kho hiện tại.
    const oldItem=db.prepare('SELECT * FROM ppe_items WHERE id=?').get(original.item_id);if(!oldItem)throw new Error('PPE gốc không còn trong master');
    const oldQty=Number(original.quantity),oldTotalBefore=Number(oldItem.current_stock),oldTotalAfter=oldTotalBefore+oldQty;
    db.prepare('UPDATE ppe_items SET current_stock=? WHERE id=?').run(oldTotalAfter,oldItem.id);
    let oldSizeBefore=null,oldSizeAfter=null;
    if(original.size_label){let sr=db.prepare('SELECT * FROM ppe_size_stocks WHERE item_id=? AND size_label=?').get(oldItem.id,original.size_label);if(!sr){db.prepare(`INSERT INTO ppe_size_stocks(item_id,size_label,current_stock,min_stock,active,updated_at) VALUES(?,?,0,0,0,?)`).run(oldItem.id,original.size_label,ts);sr={current_stock:0}}oldSizeBefore=Number(sr.current_stock||0);oldSizeAfter=oldSizeBefore+oldQty;db.prepare('UPDATE ppe_size_stocks SET current_stock=?,updated_at=? WHERE item_id=? AND size_label=?').run(oldSizeAfter,ts,oldItem.id,original.size_label)}
    const reversalId=id('ptx');
    db.prepare(`INSERT INTO ppe_transactions(id,item_id,employee_id,type,quantity,stock_before,stock_after,reason,note,actor,created_at,unit_price_snapshot,cost_amount,employee_code_snapshot,employee_name_snapshot,department_snapshot,site_snapshot,snapshot_source,size_label,size_stock_before,size_stock_after,tx_status,reversal_of_id,correction_reason,corrected_by,corrected_at,effective_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).run(reversalId,original.item_id,original.employee_id,'REVERSAL',oldQty,oldTotalBefore,oldTotalAfter,'Hoàn kho do sửa lịch sử xuất',`Hoàn giao dịch ${original.id}${original.note?` · Ghi chú cũ: ${original.note}`:''}`,who,ts,original.unit_price_snapshot,original.cost_amount==null?null:-Math.abs(Number(original.cost_amount)),original.employee_code_snapshot,original.employee_name_snapshot,original.department_snapshot,original.site_snapshot,'HISTORY_CORRECTION_REVERSAL',original.size_label,oldSizeBefore,oldSizeAfter,'active',original.id,correctionReason,who,ts,ts);
    let replacementId=null,replacement=null;
    if(mode==='correct'){
      // 2) Ghi lại lần xuất đã chỉnh sau khi hàng cũ được hoàn kho.
      newItem=db.prepare('SELECT * FROM ppe_items WHERE id=?').get(newItem.id);const newTotalBefore=Number(newItem.current_stock),newTotalAfter=newTotalBefore-newQty;
      let newSizeBefore=null,newSizeAfter=null;if(newSize){let sr=ppeOperationalSizeRow(newItem.id,newSize);if(!sr){db.prepare(`INSERT INTO ppe_size_stocks(item_id,size_label,current_stock,min_stock,active,updated_at) VALUES(?,?,0,0,1,?)`).run(newItem.id,newSize,ts);sr=ppeOperationalSizeRow(newItem.id,newSize)}newSizeBefore=Number(sr.current_stock);newSizeAfter=newSizeBefore-newQty;db.prepare('UPDATE ppe_size_stocks SET current_stock=?,updated_at=? WHERE item_id=? AND size_label=?').run(newSizeAfter,ts,newItem.id,newSize)}
      db.prepare('UPDATE ppe_items SET current_stock=? WHERE id=?').run(newTotalAfter,newItem.id);
      const price=original.item_id===newItem.id&&original.unit_price_snapshot!=null?Number(original.unit_price_snapshot):(newItem.unit_price==null?null:Number(newItem.unit_price)),cost=price==null?null:newQty*price;
      replacementId=id('ptx');const effective=original.effective_at||original.created_at;
      db.prepare(`INSERT INTO ppe_transactions(id,item_id,employee_id,type,quantity,stock_before,stock_after,reason,note,actor,created_at,unit_price_snapshot,cost_amount,employee_code_snapshot,employee_name_snapshot,department_snapshot,site_snapshot,snapshot_source,size_label,size_stock_before,size_stock_after,tx_status,correction_of_id,correction_reason,corrected_by,corrected_at,effective_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).run(replacementId,newItem.id,newEmp.id,'OUT',newQty,newTotalBefore,newTotalAfter,b.reason||original.reason||'Cấp phát',b.note??original.note,who,ts,price,cost,newEmp.employee_code||null,newEmp.full_name||null,newEmp.department||null,newEmp.site_code||null,'HISTORY_CORRECTED',newSize,newSizeBefore,newSizeAfter,'active',original.id,correctionReason,who,ts,effective);
      replacement={id:replacementId,item_id:newItem.id,employee_id:newEmp.id,quantity:newQty,size_label:newSize,stock_before:newTotalBefore,stock_after:newTotalAfter,size_stock_before:newSizeBefore,size_stock_after:newSizeAfter,negative_stock:newTotalAfter<0||(newSizeAfter!=null&&newSizeAfter<0)};
    }
    const finalStatus=mode==='cancel'?'voided':'superseded';
    db.prepare(`UPDATE ppe_transactions SET tx_status=?,superseded_by_id=?,correction_reason=?,corrected_by=?,corrected_at=? WHERE id=?`).run(finalStatus,replacementId||reversalId,correctionReason,who,ts,original.id);
    audit(mode==='cancel'?'ppe.issue_cancelled':'ppe.issue_corrected','ppe_transaction',original.id,{mode,correction_reason:correctionReason,reversal_id:reversalId,replacement_id:replacementId,original:{item_id:original.item_id,employee_id:original.employee_id,quantity:original.quantity,size_label:original.size_label},replacement},who);
    db.exec('COMMIT');json(res,200,{ok:true,mode,reversal_id:reversalId,replacement_id:replacementId,replacement});
  }catch(e){db.exec('ROLLBACK');json(res,400,{error:e.message})}
});

route('POST','/api/ppe/issue',async(req,res)=>{const b=await bodyJson(req);if(!b.employee_id||!Array.isArray(b.lines)||!b.lines.length)return json(res,400,{error:'employee_id and lines required'});const emp=db.prepare("SELECT e.*,s.code site_code FROM employees e LEFT JOIN sites s ON s.id=e.site_id WHERE e.id=? AND e.status='active'").get(b.employee_id);if(!emp)return json(res,400,{error:'active employee not found'});const out=[];db.exec('BEGIN IMMEDIATE');try{for(const line of b.lines){const qty=Number(line.quantity);if(!(qty>0))throw new Error('quantity must be >0');const p=db.prepare('SELECT * FROM ppe_items WHERE id=? AND active=1').get(line.item_id);if(!p)throw new Error('PPE item not found');const oneSize=Number(p.one_size??1)===1;let sizeLabel=null,sizeBefore=null,sizeAfter=null;if(!oneSize){sizeLabel=String(line.size_label||'').trim();const allowed=ppeSizeOptionsFromItem(p);if(!sizeLabel||!allowed.includes(sizeLabel))throw new Error(`Vui lòng chọn size hợp lệ cho ${p.name}`);let sr=ppeOperationalSizeRow(p.id,sizeLabel);if(!sr){db.prepare(`INSERT INTO ppe_size_stocks(item_id,size_label,current_stock,min_stock,active,updated_at) VALUES(?,?,0,0,1,?)`).run(p.id,sizeLabel,now());sr=ppeOperationalSizeRow(p.id,sizeLabel)}sizeBefore=Number(sr.current_stock);sizeAfter=sizeBefore-qty;db.prepare('UPDATE ppe_size_stocks SET current_stock=?,updated_at=? WHERE item_id=? AND size_label=?').run(sizeAfter,now(),p.id,sizeLabel)}const after=Number(p.current_stock)-qty,price=p.unit_price==null?null:Number(p.unit_price),cost=price==null||!Number.isFinite(price)?null:qty*price;db.prepare('UPDATE ppe_items SET current_stock=? WHERE id=?').run(after,p.id);const tid=id('ptx');db.prepare(`INSERT INTO ppe_transactions(id,item_id,employee_id,type,quantity,stock_before,stock_after,reason,note,actor,created_at,unit_price_snapshot,cost_amount,employee_code_snapshot,employee_name_snapshot,department_snapshot,site_snapshot,snapshot_source,size_label,size_stock_before,size_stock_after) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).run(tid,p.id,emp.id,'OUT',qty,p.current_stock,after,b.reason||'Cấp phát',b.note||null,actor(req,'EHS'),now(),price,cost,emp.employee_code||null,emp.full_name||null,emp.department||null,emp.site_code||null,'AT_ISSUE',sizeLabel,sizeBefore,sizeAfter);audit('ppe.issued','ppe_item',p.id,{employee_id:emp.id,qty,before:p.current_stock,after,size_label:sizeLabel,size_before:sizeBefore,size_after:sizeAfter,unit_price_snapshot:price,cost_amount:cost,negative_stock:after<0,negative_size_stock:sizeAfter!=null&&sizeAfter<0,reason:b.reason||null},actor(req,'EHS'));out.push({item_id:p.id,before:p.current_stock,after,size_label:sizeLabel,size_before:sizeBefore,size_after:sizeAfter,unit_price_snapshot:price,cost_amount:cost,negative_stock:after<0||sizeAfter!=null&&sizeAfter<0})}db.exec('COMMIT');json(res,201,{results:out})}catch(e){db.exec('ROLLBACK');json(res,400,{error:e.message})}});
route('POST','/api/ppe/adjust',async(req,res)=>{const b=await bodyJson(req),qty=Number(b.quantity);if(!b.item_id||!Number.isFinite(qty)||qty===0)return json(res,400,{error:'item_id and nonzero quantity required'});const p=db.prepare('SELECT * FROM ppe_items WHERE id=?').get(b.item_id);if(!p)return json(res,404,{error:'item not found'});let unitPrice=b.unit_price===null||b.unit_price===undefined||b.unit_price===''?p.unit_price:Number(b.unit_price);if(unitPrice!==null&&(!Number.isFinite(Number(unitPrice))||Number(unitPrice)<0))return json(res,400,{error:'unit_price must be >=0'});unitPrice=unitPrice==null?null:Number(unitPrice);const oneSize=Number(p.one_size??1)===1;let sizeLabel=null,sizeBefore=null,sizeAfter=null;if(!oneSize){sizeLabel=String(b.size_label||'').trim();const allowed=[...ppeSizeOptionsFromItem(p),PPE_UNALLOCATED_SIZE];if(!sizeLabel||!allowed.includes(sizeLabel))return json(res,400,{error:'Vui lòng chọn size cần nhập/điều chỉnh'});let sr=ppeOperationalSizeRow(p.id,sizeLabel);if(!sr){db.prepare(`INSERT INTO ppe_size_stocks(item_id,size_label,current_stock,min_stock,active,updated_at) VALUES(?,?,0,0,1,?)`).run(p.id,sizeLabel,now());sr=ppeOperationalSizeRow(p.id,sizeLabel)}sizeBefore=Number(sr.current_stock);sizeAfter=sizeBefore+qty;db.prepare('UPDATE ppe_size_stocks SET current_stock=?,updated_at=? WHERE item_id=? AND size_label=?').run(sizeAfter,now(),p.id,sizeLabel)}const after=Number(p.current_stock)+qty,type=qty>0?'IN':'ADJUSTMENT',cost=unitPrice==null?null:Math.abs(qty)*unitPrice;if(qty>0&&b.unit_price!==null&&b.unit_price!==undefined&&b.unit_price!=='')db.prepare('UPDATE ppe_items SET current_stock=?,unit_price=? WHERE id=?').run(after,unitPrice,p.id);else db.prepare('UPDATE ppe_items SET current_stock=? WHERE id=?').run(after,p.id);db.prepare(`INSERT INTO ppe_transactions(id,item_id,type,quantity,stock_before,stock_after,reason,note,actor,created_at,unit_price_snapshot,cost_amount,snapshot_source,size_label,size_stock_before,size_stock_after) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).run(id('ptx'),p.id,type,Math.abs(qty),p.current_stock,after,b.reason||'Điều chỉnh',b.note||null,actor(req,'EHS'),now(),unitPrice,cost,b.unit_price!==null&&b.unit_price!==undefined&&b.unit_price!==''?'IN_REFERENCE_UPDATE':'CURRENT_REFERENCE',sizeLabel,sizeBefore,sizeAfter);audit('ppe.adjusted','ppe_item',p.id,{delta:qty,before:p.current_stock,after,size_label:sizeLabel,size_before:sizeBefore,size_after:sizeAfter,unit_price:unitPrice},actor(req,'EHS'));json(res,200,{before:p.current_stock,after,size_label:sizeLabel,size_before:sizeBefore,size_after:sizeAfter,unit_price:unitPrice})});

route('GET','/api/obligations',async(_req,res,url)=>{const site=url.searchParams.get('site')||'',cat=url.searchParams.get('category')||'',review=url.searchParams.get('review')||'',scope=url.searchParams.get('scope')||'',status=url.searchParams.get('status')||'';const rows=db.prepare(`SELECT o.*,s.code site_code,(SELECT COUNT(*) FROM deadline_change_requests d WHERE d.obligation_id=o.id) deadline_change_count,(SELECT COUNT(*) FROM tasks t WHERE t.linked_entity_type='obligation' AND t.linked_entity_id=o.id) task_count,(SELECT COUNT(*) FROM tasks t WHERE t.linked_entity_type='obligation' AND t.linked_entity_id=o.id AND t.status='completed') task_done,(SELECT ROUND(AVG(t.progress),0) FROM tasks t WHERE t.linked_entity_type='obligation' AND t.linked_entity_id=o.id) task_progress,(SELECT COUNT(*) FROM documents d WHERE d.linked_entity_type='obligation' AND d.linked_entity_id=o.id) evidence_count FROM obligations o LEFT JOIN sites s ON s.id=o.site_id WHERE (?='' OR s.code=?) AND (?='' OR o.category=?) AND (?='' OR o.legal_review_status=?) AND (?='' OR o.source_scope=?) AND (?='' OR o.status=?) ORDER BY COALESCE(o.current_due_date,printf('%04d-%02d-28',COALESCE(o.schedule_year,2099),COALESCE(o.schedule_month,12))),o.title`).all(site,site,cat,cat,review,review,scope,scope,status,status);for(const o of rows)o.display_status=obligationStatusDerived(o);json(res,200,rows)});

route('GET','/api/compliance/overview',async(_req,res)=>{const today=new Date().toISOString().slice(0,10),p30=new Date(Date.now()+30*86400000).toISOString().slice(0,10);const rows=db.prepare(`SELECT status,current_due_date,source_scope,legal_review_status FROM obligations`).all();const out={total:rows.length,annual_plan:0,legal_extra:0,not_started:0,in_progress:0,waiting:0,blocked:0,completed:0,overdue:0,due_30:0,needs_legal_review:0};for(const o of rows){out[o.source_scope==='legal_extra'?'legal_extra':'annual_plan']++;if(out[o.status]!=null)out[o.status]++;if(o.status!=='completed'&&o.current_due_date&&o.current_due_date<today)out.overdue++;else if(o.status!=='completed'&&o.current_due_date&&o.current_due_date<=p30)out.due_30++;if(o.legal_review_status==='needs_review')out.needs_legal_review++}json(res,200,out)});
route('PATCH','/api/obligations',async(req,res)=>{const b=await bodyJson(req),o=db.prepare('SELECT * FROM obligations WHERE id=?').get(b.id);if(!o)return json(res,404,{error:'obligation not found'});const allowedStatus=['not_started','in_progress','waiting','blocked','completed','cancelled'];if(b.status&&!allowedStatus.includes(b.status))return json(res,400,{error:'invalid status'});const progress=b.progress==null?null:Math.max(0,Math.min(100,Number(b.progress)));db.prepare(`UPDATE obligations SET status=COALESCE(?,status),progress=COALESCE(?,progress),status_note=COALESCE(?,status_note),owner=COALESCE(?,owner),coordinator=COALESCE(?,coordinator),evidence_document_id=COALESCE(?,evidence_document_id),completed_at=CASE WHEN ?='completed' THEN COALESCE(completed_at,?) WHEN ? IS NOT NULL AND ?<>'completed' THEN NULL ELSE completed_at END,updated_at=? WHERE id=?`).run(b.status||null,progress,b.status_note??null,b.owner??null,b.coordinator??null,b.evidence_document_id??null,b.status||null,now(),b.status||null,b.status||null,now(),b.id);audit('obligation.updated','obligation',b.id,b,actor(req));json(res,200,{ok:true})});
route('POST','/api/compliance/legal-extra',async(req,res)=>{const b=await bodyJson(req);if(!b.title||!b.category||!b.legal_basis)return json(res,400,{error:'title/category/legal_basis required'});const oid=id('obl');db.prepare(`INSERT INTO obligations(id,title,category,requirement_type,legal_basis,source_url,site_id,owner,coordinator,original_due_date,current_due_date,status,progress,criticality,notes,source_scope,legal_review_status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).run(oid,b.title,b.category,'LEGAL',b.legal_basis,b.source_url||null,b.site_id||null,b.owner||'Phòng EHS',b.coordinator||null,b.due_date||null,b.due_date||null,'not_started',0,b.criticality||'high',b.notes||null,'legal_extra','reviewed',now(),now());audit('compliance.legal_extra_created','obligation',oid,b,actor(req));json(res,201,{id:oid})});
route('GET','/api/compliance/plan-imports',async(_req,res)=>json(res,200,db.prepare(`SELECT p.*,d.original_name FROM compliance_plan_imports p LEFT JOIN documents d ON d.id=p.document_id ORDER BY p.imported_at DESC`).all()));
route('POST','/api/compliance/plan-import',async(req,res)=>{const b=await bodyJson(req);if(!b.document_id||!db.prepare('SELECT 1 FROM documents WHERE id=?').get(b.document_id))return json(res,400,{error:'valid document_id required'});const pid=id('plan');db.prepare(`INSERT INTO compliance_plan_imports(id,document_id,plan_year,version_label,status,note,imported_by,imported_at) VALUES(?,?,?,?,?,?,?,?)`).run(pid,b.document_id,Number(b.plan_year||new Date().getFullYear()),b.version_label||null,'pending_review',b.note||'Kế hoạch mới đã tải lên; cần mapping/review trước khi thay thế obligation năm hiện tại.',actor(req),now());db.prepare(`UPDATE documents SET linked_entity_type='compliance_plan',linked_entity_id=?,status='linked' WHERE id=?`).run(pid,b.document_id);audit('compliance.plan_staged','compliance_plan',pid,{document_id:b.document_id,plan_year:b.plan_year},actor(req));json(res,201,{id:pid,status:'pending_review'})});

route('POST','/api/obligations/deadline-change',async(req,res)=>{const b=await bodyJson(req),o=db.prepare('SELECT * FROM obligations WHERE id=?').get(b.obligation_id);if(!o||!b.new_due_date||!b.reason_category||!String(b.justification||'').trim())return json(res,400,{error:'obligation,new due date,reason and justification required'});const rid=id('dcr');db.prepare(`INSERT INTO deadline_change_requests(id,obligation_id,old_due_date,new_due_date,reason_category,justification,requested_by,requested_at,status) VALUES(?,?,?,?,?,?,?,?,?)`).run(rid,o.id,o.current_due_date,b.new_due_date,b.reason_category,b.justification,actor(req),now(),'pending');audit('deadline_change.requested','obligation',o.id,{request_id:rid,old:o.current_due_date,new:b.new_due_date,reason:b.reason_category},actor(req));json(res,201,{id:rid,status:'pending'})});
route('POST','/api/obligations/deadline-change/approve',async(req,res)=>{const b=await bodyJson(req),d=db.prepare("SELECT * FROM deadline_change_requests WHERE id=? AND status='pending'").get(b.request_id);if(!d)return json(res,404,{error:'pending request not found'});const approve=!!b.approve;db.exec('BEGIN IMMEDIATE');try{db.prepare('UPDATE deadline_change_requests SET status=?,approved_by=?,approved_at=?,decision_note=? WHERE id=?').run(approve?'approved':'rejected',actor(req,'manager'),now(),b.decision_note||null,d.id);if(approve){db.prepare('UPDATE obligations SET current_due_date=?,updated_at=? WHERE id=?').run(d.new_due_date,now(),d.obligation_id);markLinkedTaskDeadlineChange('obligation',d.obligation_id,d.new_due_date);}audit(approve?'deadline_change.approved':'deadline_change.rejected','obligation',d.obligation_id,{request_id:d.id,new_due_date:d.new_due_date},actor(req,'manager'));db.exec('COMMIT');json(res,200,{ok:true,status:approve?'approved':'rejected'})}catch(e){db.exec('ROLLBACK');json(res,500,{error:e.message})}});
