route('GET','/api/legal-search',async(req,res,url)=>{
  const q=String(url.searchParams.get('q')||'').trim(),category=String(url.searchParams.get('category')||'').trim();
  if(q.length<2)return json(res,200,{query:q,results:[],official_portals:[{name:'Hệ thống văn bản Chính phủ',url:'https://vanban.chinhphu.vn/he-thong-van-ban?classid=1&mode=1'},{name:'CSDL quốc gia về VBPL',url:'https://vbpl.vn/pages/vbpq-timkiem.aspx'}]});
  const like=`%${q}%`,catSql=category?' AND category=?':'',catArgs=category?[category]:[];
  const sources=db.prepare(`SELECT id,code,title,category,document_type,issuer,issued_date,effective_date,status,official_url,verified_at,last_checked_at,last_error FROM legal_sources WHERE (code LIKE ? OR title LIKE ? OR COALESCE(issuer,'') LIKE ?)${catSql} ORDER BY effective_date DESC,issued_date DESC LIMIT 40`).all(like,like,like,...catArgs);
  const obligations=db.prepare(`SELECT id,title,category,legal_basis,current_due_date,status FROM obligations WHERE requirement_type='LEGAL' AND (title LIKE ? OR COALESCE(legal_basis,'') LIKE ?)${category?' AND category=?':''} ORDER BY current_due_date LIMIT 30`).all(like,like,...catArgs);
  const updates=db.prepare(`SELECT u.id,u.summary,u.impact_level,u.status,u.detected_at,s.code,s.title,s.category,s.official_url FROM legal_updates u JOIN legal_sources s ON s.id=u.source_id WHERE (u.summary LIKE ? OR s.code LIKE ? OR s.title LIKE ?)${category?' AND s.category=?':''} ORDER BY u.detected_at DESC LIMIT 30`).all(like,like,like,...catArgs);
  audit('legal_search.performed','legal_search',q.slice(0,120),{category,source_count:sources.length,obligation_count:obligations.length,update_count:updates.length},actor(req));
  json(res,200,{query:q,category:category||null,results:{sources,obligations,updates},official_portals:[{name:'Hệ thống văn bản Chính phủ',url:'https://vanban.chinhphu.vn/he-thong-van-ban?classid=1&mode=1'},{name:'CSDL quốc gia về VBPL',url:'https://vbpl.vn/pages/vbpq-timkiem.aspx'}],note:'Tra cứu nội bộ chỉ dựa trên Legal Register/nguồn đã được đưa vào hệ thống. Hai cổng chính thức dùng để mở rộng phạm vi; kết quả không tự thay đổi nghĩa vụ.'});
});
