route('PATCH','/api/legal-sources',async(req,res)=>{const b=await bodyJson(req),src=db.prepare('SELECT * FROM legal_sources WHERE id=?').get(b.id);if(!src)return json(res,404,{error:'legal source not found'});if(b.official_url!=null&&!/^(https?:|data:)/i.test(String(b.official_url)))return json(res,400,{error:'official_url must be https/http/data'});db.prepare(`UPDATE legal_sources SET official_url=COALESCE(?,official_url),status=COALESCE(?,status),title=COALESCE(?,title),content_hash=CASE WHEN ? IS NOT NULL AND ?<>official_url THEN NULL ELSE content_hash END,updated_at=? WHERE id=?`).run(b.official_url??null,b.status??null,b.title??null,b.official_url??null,b.official_url??null,now(),src.id);audit('legal_source.updated','legal_source',src.id,{official_url:b.official_url,status:b.status,title:b.title},actor(req));json(res,200,{ok:true})});
route('GET','/api/legal-updates',async(_req,res)=>json(res,200,db.prepare(`SELECT u.*,s.code,s.title,s.category,s.official_url,s.effective_date FROM legal_updates u JOIN legal_sources s ON s.id=u.source_id ORDER BY CASE u.status WHEN 'needs_review' THEN 0 ELSE 1 END,u.detected_at DESC`).all()));
route('POST','/api/legal-updates/resolve',async(req,res)=>{const b=await bodyJson(req);if(!b.id||!['reviewed','not_applicable','action_required'].includes(b.status)||!String(b.review_note||'').trim())return json(res,400,{error:'id,status,review_note required'});const u=db.prepare('SELECT * FROM legal_updates WHERE id=?').get(b.id);if(!u)return json(res,404,{error:'legal update not found'});db.prepare('UPDATE legal_updates SET status=?,reviewed_by=?,reviewed_at=?,review_note=? WHERE id=?').run(b.status,actor(req),now(),b.review_note,b.id);audit('legal_update.resolved','legal_update',u.id,{status:b.status,note:b.review_note},actor(req));json(res,200,{ok:true})});


route('GET','/api/documents/stats',async(_req,res)=>{const cats=db.prepare(`SELECT COALESCE(category,'other') category,COUNT(*) count,SUM(CASE WHEN status='needs_review' THEN 1 ELSE 0 END) needs_review FROM documents GROUP BY COALESCE(category,'other') ORDER BY category`).all();const subs=db.prepare(`SELECT COALESCE(category,'other') category,COALESCE(subcategory,'Chưa phân nhóm') subcategory,COUNT(*) count FROM documents GROUP BY COALESCE(category,'other'),COALESCE(subcategory,'Chưa phân nhóm') ORDER BY category,subcategory`).all();json(res,200,{total:db.prepare('SELECT COUNT(*) c FROM documents').get().c,categories:cats,subcategories:subs})});
route('GET','/api/documents',async(_req,res,url)=>{let sql=`SELECT d.*,s.code site_code,(SELECT x.doc_type FROM document_extractions x WHERE x.document_id=d.id ORDER BY x.updated_at DESC LIMIT 1) detected_type,(SELECT x.confidence FROM document_extractions x WHERE x.document_id=d.id ORDER BY x.updated_at DESC LIMIT 1) confidence,(SELECT x.status FROM document_extractions x WHERE x.document_id=d.id ORDER BY x.updated_at DESC LIMIT 1) extraction_status FROM documents d LEFT JOIN sites s ON s.id=d.site_id WHERE 1=1`,args=[];const f=k=>String(url.searchParams.get(k)||'').trim();if(f('category')){sql+=' AND d.category=?';args.push(f('category'))}if(f('subcategory')){sql+=' AND d.subcategory=?';args.push(f('subcategory'))}if(f('site')){sql+=' AND s.code=?';args.push(f('site'))}if(f('status')){sql+=' AND d.status=?';args.push(f('status'))}if(f('ocr')){sql+=f('ocr')==='unprocessed'?' AND NOT EXISTS(SELECT 1 FROM document_extractions x WHERE x.document_id=d.id)':' AND EXISTS(SELECT 1 FROM document_extractions x WHERE x.document_id=d.id AND x.status=?)';if(f('ocr')!=='unprocessed')args.push(f('ocr'))}if(f('year')){sql+=" AND strftime('%Y',COALESCE(d.document_date,d.uploaded_at))=?";args.push(f('year'))}if(f('linked')==='linked')sql+=' AND d.linked_entity_id IS NOT NULL';if(f('linked')==='unlinked')sql+=' AND d.linked_entity_id IS NULL';if(f('q')){sql+=` AND (d.original_name LIKE ? OR COALESCE(d.document_no,'') LIKE ? OR COALESCE(d.tags,'') LIKE ? OR EXISTS(SELECT 1 FROM document_extractions x WHERE x.document_id=d.id AND (COALESCE(x.text_preview,'') LIKE ? OR COALESCE(x.fields_json,'') LIKE ?)))`;const q=`%${f('q')}%`;args.push(q,q,q,q,q)}sql+=' ORDER BY d.uploaded_at DESC LIMIT 1000';json(res,200,db.prepare(sql).all(...args))});
route('POST','/api/documents',async(req,res)=>{const b=await bodyJson(req);if(!b.original_name||!b.base64)return json(res,400,{error:'original_name and base64 required'});const bytes=Buffer.from(b.base64,'base64');if(bytes.length>25*1024*1024)return json(res,413,{error:'file too large (25MB max in V1)'});const sha=crypto.createHash('sha256').update(bytes).digest('hex'),dup=db.prepare('SELECT id,original_name,uploaded_at FROM documents WHERE sha256=?').get(sha),safeExt=(extname(b.original_name)||'').toLowerCase().replace(/[^.a-z0-9]/g,'').slice(0,12),stored=`${crypto.randomUUID()}${safeExt}`;await writeFile(join(UPLOAD_DIR,stored),bytes);const did=id('doc'),ts=now();db.prepare(`INSERT INTO documents(id,original_name,stored_name,mime_type,size_bytes,sha256,category,subcategory,site_id,status,linked_entity_type,linked_entity_id,version_label,document_no,document_date,expiry_date,tags,metadata_note,uploaded_by,uploaded_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).run(did,b.original_name,stored,b.mime_type||null,bytes.length,sha,b.category||null,b.subcategory||null,b.site_id||null,'needs_review',b.linked_entity_type||null,b.linked_entity_id||null,b.version_label||null,b.document_no||null,b.document_date||null,b.expiry_date||null,b.tags||null,b.metadata_note||null,actor(req),ts,ts);audit('document.imported','document',did,{original_name:b.original_name,sha256:sha,category:b.category,subcategory:b.subcategory,duplicate_of:dup?.id||null},actor(req));json(res,201,{id:did,duplicate_of:dup||null})});
route('PATCH','/api/documents/metadata',async(req,res)=>{const b=await bodyJson(req),before=db.prepare('SELECT * FROM documents WHERE id=?').get(b.id);if(!before)return json(res,404,{error:'document not found'});const allowed=['category','subcategory','site_id','status','version_label','document_no','document_date','expiry_date','tags','metadata_note','linked_entity_type','linked_entity_id'],sets=[],vals=[];for(const k of allowed)if(Object.prototype.hasOwnProperty.call(b,k)){if(k==='status'&&!['needs_review','linked','archived'].includes(b[k]))return json(res,400,{error:'invalid status'});sets.push(`${k}=?`);vals.push(b[k]||null)}if(!sets.length)return json(res,400,{error:'no metadata fields'});sets.push('updated_at=?');vals.push(now(),b.id);db.prepare(`UPDATE documents SET ${sets.join(',')} WHERE id=?`).run(...vals);const after=db.prepare('SELECT * FROM documents WHERE id=?').get(b.id);audit('document.metadata_updated','document',b.id,{before:{category:before.category,subcategory:before.subcategory,site_id:before.site_id,status:before.status,document_no:before.document_no,document_date:before.document_date,expiry_date:before.expiry_date,tags:before.tags},after:{category:after.category,subcategory:after.subcategory,site_id:after.site_id,status:after.status,document_no:after.document_no,document_date:after.document_date,expiry_date:after.expiry_date,tags:after.tags}},actor(req));json(res,200,{ok:true,document:after})});
route('PATCH','/api/documents/review',async(req,res)=>{const b=await bodyJson(req);if(!b.id||!['needs_review','linked','archived'].includes(b.status))return json(res,400,{error:'id/status required'});db.prepare(`UPDATE documents SET status=?,category=COALESCE(?,category),linked_entity_type=COALESCE(?,linked_entity_type),linked_entity_id=COALESCE(?,linked_entity_id),updated_at=? WHERE id=?`).run(b.status,b.category||null,b.linked_entity_type||null,b.linked_entity_id||null,now(),b.id);audit('document.reviewed','document',b.id,b,actor(req));json(res,200,{ok:true})});
route('GET','/api/documents/file',async(req,res,url)=>{const d=db.prepare('SELECT * FROM documents WHERE id=?').get(url.searchParams.get('id'));if(!d)return json(res,404,{error:'document not found'});const path=join(UPLOAD_DIR,d.stored_name);try{const data=await readFile(path),inline=url.searchParams.get('inline')==='1';res.writeHead(200,securityHeaders({'Content-Type':d.mime_type||'application/octet-stream','Content-Length':data.length,'Content-Disposition':`${inline?'inline':'attachment'}; filename*=UTF-8''${encodeURIComponent(d.original_name)}`,'Cache-Control':'private, no-store'}));res.end(data)}catch{json(res,404,{error:'file bytes not found'})}});
function paymentMatchKey(v){return String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[Đđ]/g,'D').toUpperCase().replace(/[^A-Z0-9]/g,'')}
function suggestPayment(analysis){
  const v=analysis.values||{};let candidates=[];
  if(analysis.doc_type==='invoice'&&v.invoice_no){
    candidates=db.prepare(`SELECT p.id,p.title,p.invoice_no,p.invoice_date,p.amount,v.name vendor_name,v.tax_code FROM payments p JOIN vendors v ON v.id=p.vendor_id WHERE p.invoice_no=? OR (p.amount IS NOT NULL AND ? IS NOT NULL AND abs(p.amount-?)<1)`).all(String(v.invoice_no),v.amount??null,v.amount??null);
  }else if(analysis.doc_type==='payment_request'&&(v.invoice_no||v.amount!=null)){
    candidates=db.prepare(`SELECT p.id,p.title,p.invoice_no,p.invoice_date,p.amount,v.name vendor_name,v.tax_code FROM payments p JOIN vendors v ON v.id=p.vendor_id WHERE (? IS NOT NULL AND p.invoice_no=?) OR (? IS NOT NULL AND p.amount IS NOT NULL AND abs(p.amount-?)<1)`).all(v.invoice_no??null,v.invoice_no??null,v.amount??null,v.amount??null);
  }else if((analysis.doc_type==='contract'||analysis.doc_type==='acceptance_report')&&v.contract_no){
    const key=paymentMatchKey(v.contract_no);
    candidates=db.prepare(`SELECT p.id,p.title,p.invoice_no,p.invoice_date,p.amount,v.name vendor_name,c.contract_no FROM payments p JOIN vendors v ON v.id=p.vendor_id LEFT JOIN contracts c ON c.id=p.contract_id WHERE c.contract_no IS NOT NULL`).all().filter(x=>{const ck=paymentMatchKey(x.contract_no);return ck===key||ck.includes(key)||key.includes(ck)});
  }
  return candidates.map(x=>({...x,score:((analysis.doc_type==='invoice'||analysis.doc_type==='payment_request')&&v.invoice_no&&x.invoice_no===String(v.invoice_no)?0.98:0.72)})).sort((a,b)=>b.score-a.score).slice(0,5);
}
async function processIntelligence(docId,req){const d=db.prepare('SELECT * FROM documents WHERE id=?').get(docId);if(!d)throw new Error('document not found');const analysis=await analyzeDocument(join(UPLOAD_DIR,d.stored_name),d.mime_type||'',d.original_name);const matches=suggestPayment(analysis),eid=db.prepare('SELECT id FROM document_extractions WHERE document_id=?').get(docId)?.id||id('ext');db.prepare(`INSERT INTO document_extractions(id,document_id,doc_type,confidence,extraction_method,fields_json,text_preview,warnings_json,match_json,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,'needs_review',?,?) ON CONFLICT(document_id) DO UPDATE SET doc_type=excluded.doc_type,confidence=excluded.confidence,extraction_method=excluded.extraction_method,fields_json=excluded.fields_json,text_preview=excluded.text_preview,warnings_json=excluded.warnings_json,match_json=excluded.match_json,status='needs_review',updated_at=excluded.updated_at`).run(eid,docId,analysis.doc_type,analysis.confidence,analysis.extraction_method,JSON.stringify(analysis.fields),analysis.text_preview,JSON.stringify(analysis.warnings||[]),JSON.stringify(matches),now(),now());db.prepare('UPDATE documents SET extracted_json=? WHERE id=?').run(JSON.stringify({doc_type:analysis.doc_type,confidence:analysis.confidence,values:analysis.values,method:analysis.extraction_method}),docId);audit('document.intelligence_processed','document',docId,{doc_type:analysis.doc_type,confidence:analysis.confidence,method:analysis.extraction_method,matches:matches.map(x=>x.id)},actor(req));return {...analysis,id:eid,matches}}
route('POST','/api/document-intelligence/process',async(req,res)=>{const b=await bodyJson(req);if(!b.document_id)return json(res,400,{error:'document_id required'});try{json(res,200,await processIntelligence(b.document_id,req))}catch(e){json(res,400,{error:e.message})}});
route('PATCH','/api/document-intelligence/extraction',async(req,res)=>{const b=await bodyJson(req),x=db.prepare('SELECT * FROM document_extractions WHERE id=?').get(b.id);if(!x||!b.fields||typeof b.fields!=='object'||Array.isArray(b.fields))return json(res,400,{error:'id and fields object required'});if(x.status==='accepted')return json(res,409,{error:'accepted extraction is locked; reject/reprocess instead'});const current=JSON.parse(x.fields_json||'{}'),merged={...current};for(const [k,v] of Object.entries(b.fields)){merged[k]=(current[k]&&typeof current[k]==='object'&&!Array.isArray(current[k]))?{...current[k],value:v,confidence:1,edited:true}:{value:v,confidence:1,edited:true}}const finalType=b.doc_type||x.doc_type,values=Object.fromEntries(Object.entries(merged).map(([k,v])=>[k,v?.value??null])),matches=suggestPayment({doc_type:finalType,values});db.prepare(`UPDATE document_extractions SET original_fields_json=COALESCE(original_fields_json,fields_json),fields_json=?,match_json=?,doc_type=?,edited_by=?,edited_at=?,updated_at=? WHERE id=?`).run(JSON.stringify(merged),JSON.stringify(matches),finalType,actor(req),now(),now(),x.id);db.prepare('UPDATE documents SET extracted_json=? WHERE id=?').run(JSON.stringify({doc_type:finalType,values,edited:true}),x.document_id);audit('document.extraction_edited','document',x.document_id,{extraction_id:x.id,changed_fields:Object.keys(b.fields),doc_type:finalType,matches:matches.map(m=>m.id)},actor(req));json(res,200,{ok:true,values:merged,matches})});

route('GET','/api/document-extractions',async(_req,res)=>{const rows=db.prepare(`SELECT x.*,d.original_name,d.category,d.site_id,s.code site_code FROM document_extractions x JOIN documents d ON d.id=x.document_id LEFT JOIN sites s ON s.id=d.site_id ORDER BY CASE x.status WHEN 'needs_review' THEN 0 ELSE 1 END,x.updated_at DESC`).all();for(const x of rows){x.fields=JSON.parse(x.fields_json||'{}');x.matches=JSON.parse(x.match_json||'[]');x.warnings=JSON.parse(x.warnings_json||'[]')}json(res,200,rows)});
route('POST','/api/document-intelligence/review',async(req,res)=>{const b=await bodyJson(req),x=db.prepare('SELECT * FROM document_extractions WHERE id=?').get(b.id);if(!x||!['accepted','rejected'].includes(b.status))return json(res,400,{error:'valid id/status required'});const paymentId=b.payment_id||null;db.exec('BEGIN IMMEDIATE');try{db.prepare('UPDATE document_extractions SET status=?,matched_payment_id=?,reviewed_by=?,reviewed_at=?,review_note=?,updated_at=? WHERE id=?').run(b.status,paymentId,actor(req),now(),b.review_note||null,now(),x.id);if(b.status==='accepted'){const map={invoice:'Hóa đơn',contract:'Hợp đồng',weight_ticket:'Phiếu cân',acceptance_report:'BBNT',payment_request:'Đề nghị thanh toán'};if(paymentId){db.prepare("UPDATE documents SET status='linked',linked_entity_type='payment',linked_entity_id=? WHERE id=?").run(paymentId,x.document_id);const dt=map[x.doc_type];if(dt){db.prepare(`INSERT OR IGNORE INTO payment_documents(id,payment_id,document_id,doc_type,created_by,created_at) VALUES(?,?,?,?,?,?)`).run(id('pdoc'),paymentId,x.document_id,dt,actor(req),now());db.prepare('UPDATE payment_required_docs SET received=1,document_id=COALESCE(document_id,?) WHERE payment_id=? AND doc_type=?').run(x.document_id,paymentId,dt)}}}audit('document.intelligence_reviewed','document',x.document_id,{extraction_id:x.id,status:b.status,payment_id:paymentId},actor(req));db.exec('COMMIT');json(res,200,{ok:true})}catch(e){db.exec('ROLLBACK');json(res,500,{error:e.message})}});


