route('GET','/api/contracts',async(_req,res,url)=>{const vendor=url.searchParams.get('vendor_id')||'';json(res,200,db.prepare(`SELECT c.*,v.name vendor_name FROM contracts c JOIN vendors v ON v.id=c.vendor_id WHERE c.active=1 AND (?='' OR c.vendor_id=?) ORDER BY c.signed_date DESC`).all(vendor,vendor))});
route('POST','/api/payments',async(req,res)=>{const b=await bodyJson(req);const vendorName=String(b.vendor_name||'').trim();let vendorId=String(b.vendor_id||'').trim()||null;if(!vendorId&&vendorName){const vendorKey=vendorName.toLocaleLowerCase('vi-VN');const existing=db.prepare('SELECT id,name FROM vendors WHERE active=1').all().find(v=>String(v.name||'').trim().toLocaleLowerCase('vi-VN')===vendorKey);if(existing)vendorId=existing.id}if(vendorId&&!db.prepare('SELECT 1 FROM vendors WHERE id=? AND active=1').get(vendorId))return json(res,400,{error:'vendor not found/inactive'});if(!vendorId&&!vendorName)return json(res,400,{error:'vendor_name/title/category required'});if(!b.title||!b.category)return json(res,400,{error:'vendor_name/title/category required'});if(!PAYMENT_CHECKLIST_RULES[b.category])return json(res,400,{error:'unknown payment category'});const contract=b.contract_id&&vendorId?db.prepare('SELECT * FROM contracts WHERE id=? AND vendor_id=?').get(b.contract_id,vendorId):null;if(b.contract_id&&!contract)return json(res,400,{error:'contract does not match vendor'});let contractualDue=b.contractual_due_date||null;if(!contractualDue&&b.invoice_date&&contract?.payment_term_days){const d=new Date(`${b.invoice_date}T00:00:00Z`);d.setUTCDate(d.getUTCDate()+Number(contract.payment_term_days));contractualDue=d.toISOString().slice(0,10)}const planned=b.planned_payment_date||null;if(planned&&contractualDue&&planned>contractualDue&&!String(b.explanation_if_late||'').trim())return json(res,400,{error:'explanation required when planned date exceeds contract due date'});const pid=id('pay'),newVendor=!vendorId;if(newVendor)vendorId=id('ven');db.exec('BEGIN IMMEDIATE');try{if(newVendor){db.prepare('INSERT INTO vendors(id,name,active) VALUES(?,?,1)').run(vendorId,vendorName);audit('vendor.created_from_payment','vendor',vendorId,{name:vendorName,source:'payment_free_text'},actor(req))}db.prepare(`INSERT INTO payments(id,vendor_id,contract_id,site_id,title,category,invoice_no,invoice_date,amount,contractual_due_date,planned_payment_date,status,owner,explanation_if_late,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).run(pid,vendorId,b.contract_id||null,b.site_id||null,b.title,b.category,b.invoice_no||null,b.invoice_date||null,b.amount==null?null:Number(b.amount),contractualDue,planned,'collecting_docs',b.owner||'Phòng EHS',b.explanation_if_late||null,now(),now());for(const d of paymentChecklist(b.category,b.amount))db.prepare(`INSERT INTO payment_required_docs(id,payment_id,doc_type,required,received,note) VALUES(?,?,?,?,0,?)`).run(id('prd'),pid,d.doc_type,d.required?1:0,d.note||null);audit('payment.created','payment',pid,{category:b.category,contractual_due_date:contractualDue,title:b.title,vendor_id:vendorId,vendor_name:vendorName||null},actor(req));db.exec('COMMIT');json(res,201,{id:pid,vendor_id:vendorId,contractual_due_date:contractualDue})}catch(e){db.exec('ROLLBACK');json(res,500,{error:e.message})}});
route('GET','/api/payments',async(_req,res)=>{const rows=db.prepare(`SELECT p.*,v.name vendor_name,c.contract_no,c.payment_term_days,s.code site_code FROM payments p JOIN vendors v ON v.id=p.vendor_id LEFT JOIN contracts c ON c.id=p.contract_id LEFT JOIN sites s ON s.id=p.site_id ORDER BY COALESCE(p.contractual_due_date,'9999-12-31')`).all();for(const p of rows){p.docs=db.prepare('SELECT * FROM payment_required_docs WHERE payment_id=? ORDER BY required DESC,doc_type').all(p.id);for(const d of p.docs)d.evidence_state=d.document_id?'linked':d.received?'declared':'missing';p.linked_documents=db.prepare(`SELECT pd.*,d.original_name,d.status document_status FROM payment_documents pd JOIN documents d ON d.id=pd.document_id WHERE pd.payment_id=? ORDER BY pd.created_at`).all(p.id);const xs=db.prepare("SELECT doc_type,fields_json,confidence FROM document_extractions WHERE matched_payment_id=? AND status='accepted'").all(p.id);let invoiceQty=null,weightTotal=0,weightCount=0,bbntCount=0;for(const x of xs){const f=JSON.parse(x.fields_json||'{}'),val=k=>f[k]?.value??null;if(x.doc_type==='invoice'&&val('quantity')!=null)invoiceQty=Number(val('quantity'));if(x.doc_type==='weight_ticket'&&val('net_kg')!=null){weightTotal+=Number(val('net_kg'));weightCount++}if(x.doc_type==='acceptance_report')bbntCount++}const variance=invoiceQty!=null&&weightCount?weightTotal-invoiceQty:null,tol=Number(p.weight_tolerance_kg||0);const weight_status=invoiceQty==null?'invoice_quantity_missing':!weightCount?'weight_ticket_missing':Math.abs(variance)<=tol?'matched':'mismatch';p.intelligence={accepted_docs:xs.length,invoice_quantity_kg:invoiceQty,weight_ticket_total_kg:weightTotal||null,weight_ticket_count:weightCount,weight_variance_kg:variance,weight_tolerance_kg:tol,weight_status,bbnt_count:bbntCount}}json(res,200,rows)});
route('POST','/api/payments/doc-toggle',async(req,res)=>{const b=await bodyJson(req),row=db.prepare('SELECT * FROM payment_required_docs WHERE id=?').get(b.id);if(!row)return json(res,404,{error:'doc row not found'});db.prepare('UPDATE payment_required_docs SET received=? WHERE id=?').run(b.received?1:0,b.id);audit('payment.document_status','payment',row.payment_id,{doc_type:row.doc_type,received:!!b.received},actor(req));json(res,200,{ok:true})});
route('PATCH','/api/payments',async(req,res)=>{const b=await bodyJson(req),p=db.prepare('SELECT * FROM payments WHERE id=?').get(b.id);if(!p)return json(res,404,{error:'payment not found'});const planned=b.planned_payment_date||p.planned_payment_date,lateNote=b.explanation_if_late??p.explanation_if_late;if(planned&&p.contractual_due_date&&planned>p.contractual_due_date&&!String(lateNote||'').trim())return json(res,400,{error:'explanation required when planned date exceeds contract due date'});if(b.weight_tolerance_kg!=null&&Number(b.weight_tolerance_kg)<0)return json(res,400,{error:'weight_tolerance_kg must be >=0'});db.prepare(`UPDATE payments SET planned_payment_date=COALESCE(?,planned_payment_date),status=COALESCE(?,status),explanation_if_late=COALESCE(?,explanation_if_late),paid_date=COALESCE(?,paid_date),weight_tolerance_kg=COALESCE(?,weight_tolerance_kg),updated_at=? WHERE id=?`).run(b.planned_payment_date||null,b.status||null,b.explanation_if_late||null,b.paid_date||null,b.weight_tolerance_kg==null?null:Number(b.weight_tolerance_kg),now(),b.id);audit('payment.updated','payment',b.id,b,actor(req));json(res,200,{ok:true})});

route('GET','/api/equipment',async(_req,res)=>{const rows=db.prepare(`SELECT e.*,s.code site_code,(SELECT COUNT(*) FROM equipment_inspections i WHERE i.equipment_id=e.id) inspection_count,(SELECT COUNT(*) FROM equipment_documents d WHERE d.equipment_id=e.id) document_count FROM equipment e LEFT JOIN sites s ON s.id=e.site_id ORDER BY COALESCE(next_inspection_date,'9999-12-31'),asset_code`).all();const today=new Date().toISOString().slice(0,10);for(const e of rows){e.inspection_state=!e.next_inspection_date?'no_due_date':e.next_inspection_date<today?'expired':e.next_inspection_date<=new Date(Date.now()+60*86400000).toISOString().slice(0,10)?'due_60':'valid'}json(res,200,rows)});
