route('GET','/api/equipment/reconciliations',async(_req,res,url)=>{const eid=url.searchParams.get('equipment_id')||'';json(res,200,db.prepare(`SELECT * FROM equipment_reconciliations WHERE (?='' OR equipment_id=?) ORDER BY reconciled_at DESC`).all(eid,eid))});
route('POST','/api/equipment/reconcile',async(req,res)=>{const b=await bodyJson(req),e=db.prepare('SELECT * FROM equipment WHERE id=?').get(b.equipment_id);if(!e||!b.fields||typeof b.fields!=='object')return json(res,400,{error:'equipment_id and fields required'});const allowed=['asset_code','name','category','manufacturer','model','serial_no','manufacture_year','site_id','location','manager','operator','last_inspection_date','next_inspection_date','status','source_country','inspection_number','department','company','remarks','machine_description','legal_basis','applicability_condition','strict_control'];const fields=Object.fromEntries(Object.entries(b.fields).filter(([k])=>allowed.includes(k)));if(!Object.keys(fields).length)return json(res,400,{error:'no allowed fields'});const before=Object.fromEntries(Object.keys(fields).map(k=>[k,e[k]]));const sets=Object.keys(fields).map(k=>`${k}=?`).join(','),vals=Object.keys(fields).map(k=>k==='strict_control'?(fields[k]?1:0):fields[k]);db.exec('BEGIN IMMEDIATE');try{db.prepare(`UPDATE equipment SET ${sets},review_status=?,reconciled_at=?,reconciled_by=?,updated_at=? WHERE id=?`).run(...vals,b.finalize?'reviewed':'needs_review',now(),actor(req),now(),e.id);db.prepare(`INSERT INTO equipment_reconciliations(id,equipment_id,source_ref,before_json,after_json,note,finalized,reconciled_by,reconciled_at) VALUES(?,?,?,?,?,?,?,?,?)`).run(id('eqr'),e.id,e.source_ref||null,JSON.stringify(before),JSON.stringify(fields),b.note||null,b.finalize?1:0,actor(req),now());audit('equipment.reconciled','equipment',e.id,{fields:Object.keys(fields),finalize:!!b.finalize,note:b.note||null},actor(req));db.exec('COMMIT');ensureEquipmentReminder(db.prepare('SELECT * FROM equipment WHERE id=?').get(e.id));json(res,200,{ok:true})}catch(err){db.exec('ROLLBACK');json(res,500,{error:err.message})}});
route('GET','/api/tasks',async(_req,res,url)=>{const status=url.searchParams.get('status')||'',owner=url.searchParams.get('owner')||'';const rows=db.prepare(`SELECT t.*,s.code site_code,(SELECT COUNT(*) FROM documents d WHERE d.linked_entity_type='task' AND d.linked_entity_id=t.id AND d.status='linked') evidence_count,(SELECT COUNT(*) FROM task_recurrence_history h WHERE h.task_id=t.id) recurrence_completed_count,CASE WHEN t.linked_entity_type='obligation' THEN (SELECT title FROM obligations o WHERE o.id=t.linked_entity_id) WHEN t.linked_entity_type='equipment' THEN (SELECT asset_code||' · '||name FROM equipment e WHERE e.id=t.linked_entity_id) WHEN t.linked_entity_type='payment' THEN (SELECT title FROM payments p WHERE p.id=t.linked_entity_id) ELSE NULL END linked_title FROM tasks t LEFT JOIN sites s ON s.id=t.site_id WHERE (?='' OR t.status=?) AND (?='' OR t.owner LIKE '%'||?||'%') ORDER BY CASE t.status WHEN 'in_progress' THEN 0 WHEN 'blocked' THEN 1 WHEN 'waiting' THEN 2 WHEN 'not_started' THEN 3 WHEN 'completed' THEN 4 ELSE 5 END,COALESCE(t.due_date,'9999-12-31')`).all(status,status,owner,owner);json(res,200,rows)});
route('POST','/api/tasks',async(req,res)=>{const b=await bodyJson(req);if(!b.title)return json(res,400,{error:'title required'});if(!validRecurrence(b.recurrence))return json(res,400,{error:'invalid recurrence'});let due=b.due_date||null,sourceDue=null;if(b.linked_entity_type==='obligation'&&b.linked_entity_id){sourceDue=db.prepare('SELECT current_due_date FROM obligations WHERE id=?').get(b.linked_entity_id)?.current_due_date||null;if(!due)due=sourceDue}const recurrence=b.recurrence||null;if(recurrence&&!due)return json(res,400,{error:'Công việc lặp lại cần có deadline/kỳ đầu tiên'});const recurrenceInterval=Math.max(1,Math.min(365,Number(b.recurrence_interval)||1)),recurrenceEnd=b.recurrence_end_date||null;if(recurrenceEnd&&due&&recurrenceEnd<due)return json(res,400,{error:'Ngày kết thúc chu kỳ phải từ deadline đầu tiên trở đi'});const status=['not_started','in_progress','waiting','blocked','completed'].includes(b.status)?b.status:'not_started',progress=status==='completed'?100:Math.max(0,Math.min(100,Number(b.progress||0)));const tid=id('task');db.prepare(`INSERT INTO tasks(id,title,category,site_id,owner,due_date,recurrence,recurrence_interval,recurrence_end_date,priority,status,progress,notes,blocked_reason,source_due_date,deadline_sync_state,linked_entity_type,linked_entity_id,started_at,completed_at,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).run(tid,b.title,b.category||null,b.site_id||null,b.owner||null,due,recurrence,recurrenceInterval,recurrenceEnd,b.priority||'medium',status,progress,b.notes||null,b.blocked_reason||null,sourceDue,sourceDue&&due!==sourceDue?'custom':'synced',b.linked_entity_type||null,b.linked_entity_id||null,status==='in_progress'?now():null,status==='completed'?now():null,now(),now());audit('task.created','task',tid,b,actor(req));json(res,201,{id:tid,recurrence,recurrence_interval:recurrenceInterval,recurrence_end_date:recurrenceEnd})});
route('PATCH','/api/tasks',async(req,res)=>{const b=await bodyJson(req);let t=db.prepare('SELECT * FROM tasks WHERE id=?').get(b.id);if(!t)return json(res,404,{error:'task not found'});const statuses=['not_started','in_progress','waiting','blocked','completed','cancelled'];if(b.status&&!statuses.includes(b.status))return json(res,400,{error:'invalid status'});if(Object.prototype.hasOwnProperty.call(b,'recurrence')&&!validRecurrence(b.recurrence))return json(res,400,{error:'invalid recurrence'});const recurrenceTouched=Object.prototype.hasOwnProperty.call(b,'recurrence')||Object.prototype.hasOwnProperty.call(b,'recurrence_interval')||Object.prototype.hasOwnProperty.call(b,'recurrence_end_date');if(recurrenceTouched){const recurrence=Object.prototype.hasOwnProperty.call(b,'recurrence')?(b.recurrence||null):t.recurrence,interval=Object.prototype.hasOwnProperty.call(b,'recurrence_interval')?Math.max(1,Math.min(365,Number(b.recurrence_interval)||1)):Number(t.recurrence_interval||1),endDate=Object.prototype.hasOwnProperty.call(b,'recurrence_end_date')?(b.recurrence_end_date||null):t.recurrence_end_date,due=Object.prototype.hasOwnProperty.call(b,'due_date')?(b.due_date||t.due_date):t.due_date;if(recurrence&&!due)return json(res,400,{error:'Công việc lặp lại cần có deadline'});if(endDate&&due&&endDate<due)return json(res,400,{error:'Ngày kết thúc chu kỳ phải từ deadline hiện tại trở đi'});db.prepare('UPDATE tasks SET recurrence=?,recurrence_interval=?,recurrence_end_date=?,updated_at=? WHERE id=?').run(recurrence,interval,endDate,now(),b.id);t=db.prepare('SELECT * FROM tasks WHERE id=?').get(b.id)}let progress=b.progress==null?t.progress:Math.max(0,Math.min(100,Number(b.progress)));const isRecurringCompletion=b.status==='completed'&&t.recurrence&&t.due_date;if(isRecurringCompletion){const completedAt=now(),next=nextRecurringDate(t.due_date,t.recurrence,t.recurrence_interval),allowedNext=next&&(!t.recurrence_end_date||next<=t.recurrence_end_date);db.prepare(`INSERT OR REPLACE INTO task_recurrence_history(id,task_id,scheduled_date,completed_at,completed_by,next_due_date,note) VALUES(?,?,?,?,?,?,?)`).run(id('trh'),t.id,t.due_date,completedAt,actor(req),allowedNext?next:null,b.notes??t.notes??null);if(allowedNext){db.prepare(`UPDATE tasks SET status='not_started',progress=0,due_date=?,owner=COALESCE(?,owner),priority=COALESCE(?,priority),notes=COALESCE(?,notes),blocked_reason=NULL,started_at=NULL,completed_at=NULL,deadline_sync_state=CASE WHEN source_due_date IS NOT NULL AND ?=source_due_date THEN 'synced' ELSE deadline_sync_state END,updated_at=? WHERE id=?`).run(next,b.owner??null,b.priority||null,b.notes??null,next,now(),b.id);audit('task.recurrence_completed','task',b.id,{scheduled_date:t.due_date,next_due_date:next,recurrence:t.recurrence,interval:t.recurrence_interval},actor(req));return json(res,200,{ok:true,recurring:true,completed_occurrence:t.due_date,next_due_date:next})}progress=100;db.prepare(`UPDATE tasks SET status='completed',progress=100,completed_at=?,owner=COALESCE(?,owner),priority=COALESCE(?,priority),notes=COALESCE(?,notes),updated_at=? WHERE id=?`).run(completedAt,b.owner??null,b.priority||null,b.notes??null,now(),b.id);audit('task.recurrence_finished','task',b.id,{scheduled_date:t.due_date,recurrence_end_date:t.recurrence_end_date},actor(req));return json(res,200,{ok:true,recurring:true,series_finished:true,completed_occurrence:t.due_date})}if(b.status==='completed')progress=100;const started=(b.status==='in_progress'&&!t.started_at)?now():t.started_at,completed=b.status==='completed'?(t.completed_at||now()):(b.status&&b.status!=='completed'?null:t.completed_at);db.prepare(`UPDATE tasks SET status=COALESCE(?,status),progress=?,due_date=COALESCE(?,due_date),owner=COALESCE(?,owner),priority=COALESCE(?,priority),notes=COALESCE(?,notes),blocked_reason=COALESCE(?,blocked_reason),started_at=?,completed_at=?,deadline_sync_state=CASE WHEN ? IS NOT NULL THEN CASE WHEN source_due_date IS NOT NULL AND ?=source_due_date THEN 'synced' ELSE 'custom' END ELSE deadline_sync_state END,updated_at=? WHERE id=?`).run(b.status||null,progress,b.due_date||null,b.owner??null,b.priority||null,b.notes??null,b.blocked_reason??null,started,completed,b.due_date||null,b.due_date||null,now(),b.id);audit('task.updated','task',b.id,b,actor(req));json(res,200,{ok:true})});
route('GET','/api/tasks/recurrence-history',async(_req,res,url)=>{const taskId=url.searchParams.get('task_id')||'';const rows=db.prepare(`SELECT h.*,t.title FROM task_recurrence_history h JOIN tasks t ON t.id=h.task_id WHERE (?='' OR h.task_id=?) ORDER BY h.scheduled_date DESC`).all(taskId,taskId);json(res,200,rows)});

// ===== Checkpoint 5.3: Daily cockpit / inbox / evidence / calendar =====
route('POST','/api/evidence/link',async(req,res)=>{const b=await bodyJson(req);const types={obligation:'obligations',task:'tasks',equipment:'equipment',payment:'payments'};const table=types[b.entity_type];if(!table||!b.entity_id||!b.document_id)return json(res,400,{error:'entity_type, entity_id, document_id required'});if(!db.prepare(`SELECT 1 FROM ${table} WHERE id=?`).get(b.entity_id))return json(res,404,{error:'target entity not found'});const d=db.prepare('SELECT * FROM documents WHERE id=?').get(b.document_id);if(!d)return json(res,404,{error:'document not found'});db.exec('BEGIN IMMEDIATE');try{db.prepare("UPDATE documents SET status='linked',linked_entity_type=?,linked_entity_id=? WHERE id=?").run(b.entity_type,b.entity_id,b.document_id);if(b.entity_type==='payment'){if(!b.evidence_type)throw new Error('evidence_type required for payment');db.prepare(`INSERT OR IGNORE INTO payment_documents(id,payment_id,document_id,doc_type,created_by,created_at) VALUES(?,?,?,?,?,?)`).run(id('pdoc'),b.entity_id,b.document_id,b.evidence_type,actor(req),now());db.prepare('UPDATE payment_required_docs SET received=1,document_id=? WHERE payment_id=? AND doc_type=?').run(b.document_id,b.entity_id,b.evidence_type)}if(b.entity_type==='equipment')db.prepare(`INSERT OR IGNORE INTO equipment_documents(id,equipment_id,document_id,doc_type,created_by,created_at) VALUES(?,?,?,?,?,?)`).run(id('edoc'),b.entity_id,b.document_id,b.evidence_type||'evidence',actor(req),now());audit('evidence.linked',b.entity_type,b.entity_id,{document_id:b.document_id,evidence_type:b.evidence_type||null,original_name:d.original_name,note:b.note||null},actor(req));db.exec('COMMIT');json(res,200,{ok:true})}catch(e){db.exec('ROLLBACK');json(res,400,{error:e.message})}});

route('GET','/api/data-quality',async(_req,res)=>{const issues=[];const push=(code,title,count,level,view,note)=>{if(Number(count)>0)issues.push({code,title,count:Number(count),level,view,note})};push('ppe_inactive_stock','Loại PPE đã ngừng nhưng vẫn còn tồn',db.prepare("SELECT COUNT(*) c FROM ppe_items WHERE active=0 AND current_stock<>0").get().c,'warning','ppe','Kiểm tra lý do ngừng sử dụng và xử lý tồn còn lại.');push('ppe_negative','PPE âm kho',db.prepare('SELECT COUNT(*) c FROM ppe_items WHERE current_stock<0').get().c,'critical','ppe','Cần đối chiếu Stock Ledger với tồn thực tế.');push('completed_no_evidence','Compliance hoàn thành chưa có evidence',db.prepare(`SELECT COUNT(*) c FROM obligations o WHERE o.status='completed' AND o.evidence_document_id IS NULL AND NOT EXISTS(SELECT 1 FROM documents d WHERE d.linked_entity_type='obligation' AND d.linked_entity_id=o.id AND d.status='linked')`).get().c,'warning','compliance','Không nên đóng nghĩa vụ mà thiếu bằng chứng.');push('payment_missing','Payment còn thiếu chứng từ bắt buộc',db.prepare(`SELECT COUNT(DISTINCT p.id) c FROM payments p JOIN payment_required_docs d ON d.payment_id=p.id WHERE p.status NOT IN ('paid','archived') AND d.required=1 AND d.document_id IS NULL`).get().c,'warning','payments','Kiểm tra checklist hồ sơ thanh toán.');push('payment_declared_only','Chứng từ payment chỉ tick nhưng chưa upload',db.prepare(`SELECT COUNT(*) c FROM payment_required_docs WHERE received=1 AND document_id IS NULL`).get().c,'warning','payments','Đã khai báo có nhưng chưa có file evidence.');push('equipment_review','Thiết bị chưa đối chiếu nguồn',db.prepare(`SELECT COUNT(*) c FROM equipment WHERE review_status='needs_review'`).get().c,'warning','equipment','Đối chiếu với master/chứng thư gốc.');push('equipment_no_serial','Thiết bị thiếu serial',db.prepare(`SELECT COUNT(*) c FROM equipment WHERE status='active' AND (serial_no IS NULL OR trim(serial_no)='')`).get().c,'info','equipment','Bổ sung nếu thiết bị có serial/production number.');push('inactive_asset_owner','Thiết bị gắn người quản lý/vận hành đã inactive',db.prepare(`SELECT COUNT(*) c FROM equipment e WHERE EXISTS(SELECT 1 FROM employees x WHERE x.status='inactive' AND (x.id=e.manager_employee_id OR x.id=e.operator_employee_id))`).get().c,'critical','equipment','Cần bàn giao trách nhiệm quản lý thiết bị.');json(res,200,{score:Math.max(0,100-issues.reduce((a,x)=>a+(x.level==='critical'?8:x.level==='warning'?4:1),0)),issues})});

route('GET','/api/inbox',async(_req,res)=>{const items=[];const add=(kind,priority,title,subtitle,status,entity_type,entity_id,view,due_date=null,created_at=null)=>items.push({kind,priority,title,subtitle,status,entity_type,entity_id,view,due_date,created_at});for(const x of db.prepare(`SELECT x.id extraction_id,x.document_id,x.doc_type,x.confidence,x.updated_at,d.original_name FROM document_extractions x JOIN documents d ON d.id=x.document_id WHERE x.status='needs_review' ORDER BY x.updated_at DESC`).all())add('OCR','high',`OCR cần duyệt: ${x.original_name}`,`${x.doc_type} · confidence ${Math.round(Number(x.confidence||0)*100)}%`,'needs_review','document',x.document_id,'documents',null,x.updated_at);for(const d of db.prepare(`SELECT d.* FROM documents d LEFT JOIN document_extractions x ON x.document_id=d.id WHERE d.status='needs_review' AND x.id IS NULL ORDER BY d.uploaded_at DESC LIMIT 100`).all())add('Document','medium',`File mới: ${d.original_name}`,`${d.category||'other'} · chưa phân loại/OCR`,'needs_review','document',d.id,'documents',null,d.uploaded_at);for(const x of db.prepare(`SELECT u.*,s.code FROM legal_updates u JOIN legal_sources s ON s.id=u.source_id WHERE u.status='needs_review' ORDER BY u.detected_at DESC`).all())add('Legal Update','critical',`Luật cần review: ${x.code}`,x.summary,'needs_review','legal_update',x.id,'compliance',null,x.detected_at);for(const x of db.prepare(`SELECT q.*,o.title FROM legal_review_queue q LEFT JOIN obligations o ON o.id=q.entity_id WHERE q.status='needs_review' ORDER BY q.created_at DESC`).all())add('Legal Review','high',`Rà căn cứ: ${x.title||x.entity_id}`,x.reason,'needs_review','obligation',x.entity_id,'compliance',null,x.created_at);for(const x of db.prepare(`SELECT r.*,o.title FROM deadline_change_requests r JOIN obligations o ON o.id=r.obligation_id WHERE r.status='pending' ORDER BY r.requested_at DESC`).all())add('Approval','high',`Xin đổi hạn: ${x.title}`,`${x.old_due_date||'—'} → ${x.new_due_date} · ${x.reason_category}`,'pending','obligation',x.obligation_id,'compliance',x.new_due_date,x.requested_at);for(const p of db.prepare(`SELECT p.id,p.title,v.name vendor_name,p.contractual_due_date,COUNT(*) missing FROM payments p JOIN vendors v ON v.id=p.vendor_id JOIN payment_required_docs d ON d.payment_id=p.id WHERE p.status NOT IN ('paid','archived') AND d.required=1 AND d.document_id IS NULL GROUP BY p.id HAVING COUNT(*)>0 ORDER BY COALESCE(p.contractual_due_date,'9999-12-31')`).all())add('Payment','high',`Thiếu hồ sơ: ${p.title}`,`${p.vendor_name} · thiếu ${p.missing} chứng từ`,'missing_docs','payment',p.id,'payments',p.contractual_due_date,null);for(const e of db.prepare(`SELECT id,asset_code,name,source_ref FROM equipment WHERE review_status='needs_review' ORDER BY asset_code`).all())add('Equipment','medium',`Đối chiếu thiết bị: ${e.asset_code}`,`${e.name} · ${e.source_ref||'nguồn ảnh'}`,'needs_review','equipment',e.id,'equipment');const rank={critical:0,high:1,medium:2,low:3};items.sort((a,b)=>(rank[a.priority]??9)-(rank[b.priority]??9)||String(a.due_date||'9999').localeCompare(String(b.due_date||'9999'))||String(b.created_at||'').localeCompare(String(a.created_at||'')));json(res,200,items.slice(0,300))});

route('GET','/api/calendar',async(_req,res,url)=>{const start=url.searchParams.get('start')||new Date().toISOString().slice(0,8)+'01',end=url.searchParams.get('end')||'9999-12-31';const ev=[];for(const x of db.prepare(`SELECT t.id,t.title,t.due_date date,t.status,s.code site FROM tasks t LEFT JOIN sites s ON s.id=t.site_id WHERE t.due_date BETWEEN ? AND ? AND t.status<>'cancelled' AND (t.recurrence IS NULL OR t.recurrence='')`).all(start,end))ev.push({type:'task',...x,view:'tasks',recurring:false});for(const t of db.prepare(`SELECT t.*,s.code site FROM tasks t LEFT JOIN sites s ON s.id=t.site_id WHERE t.recurrence IS NOT NULL AND t.recurrence<>'' AND t.status NOT IN ('cancelled','completed')`).all())for(const d of recurrenceEvents(t,start,end))ev.push({type:'task',id:t.id,title:t.title,date:d,status:d===t.due_date?t.status:'scheduled',site:t.site,view:'tasks',recurring:true,recurrence:t.recurrence});for(const h of db.prepare(`SELECT h.task_id id,t.title,h.scheduled_date date,'completed' status,s.code site,t.recurrence FROM task_recurrence_history h JOIN tasks t ON t.id=h.task_id LEFT JOIN sites s ON s.id=t.site_id WHERE h.scheduled_date BETWEEN ? AND ?`).all(start,end))ev.push({type:'task',...h,view:'tasks',recurring:true,completed_occurrence:true});for(const x of db.prepare(`SELECT o.id,o.title,o.current_due_date date,o.status,s.code site FROM obligations o LEFT JOIN sites s ON s.id=o.site_id WHERE o.current_due_date BETWEEN ? AND ? AND o.status<>'cancelled'`).all(start,end))ev.push({type:'compliance',...x,view:'compliance'});for(const x of db.prepare(`SELECT p.id,p.title,p.contractual_due_date date,p.status,s.code site FROM payments p LEFT JOIN sites s ON s.id=p.site_id WHERE p.contractual_due_date BETWEEN ? AND ? AND p.status NOT IN ('archived')`).all(start,end))ev.push({type:'payment',...x,view:'payments'});for(const x of db.prepare(`SELECT e.id,e.asset_code||' · '||e.name title,e.next_inspection_date date,e.status,s.code site FROM equipment e LEFT JOIN sites s ON s.id=e.site_id WHERE e.next_inspection_date BETWEEN ? AND ? AND e.status='active'`).all(start,end))ev.push({type:'equipment',...x,view:'equipment'});ev.sort((a,b)=>a.date.localeCompare(b.date)||a.type.localeCompare(b.type)||a.title.localeCompare(b.title,'vi'));json(res,200,{start,end,events:ev})});

route('GET','/api/my-day',async(_req,res)=>{refreshNotifications();const today=new Date().toISOString().slice(0,10),plus7=new Date(Date.now()+7*86400000).toISOString().slice(0,10),plus30=new Date(Date.now()+30*86400000).toISOString().slice(0,10);const tasks=db.prepare(`SELECT t.*,s.code site_code,(SELECT COUNT(*) FROM documents d WHERE d.linked_entity_type='task' AND d.linked_entity_id=t.id AND d.status='linked') evidence_count FROM tasks t LEFT JOIN sites s ON s.id=t.site_id WHERE t.status NOT IN ('completed','cancelled') AND (t.status IN ('in_progress','blocked','waiting') OR t.due_date<=?) ORDER BY CASE WHEN t.due_date<? THEN 0 WHEN t.status='blocked' THEN 1 WHEN t.status='in_progress' THEN 2 ELSE 3 END,COALESCE(t.due_date,'9999-12-31') LIMIT 20`).all(plus7,today);const obligations=db.prepare(`SELECT o.*,s.code site_code,(SELECT COUNT(*) FROM documents d WHERE d.linked_entity_type='obligation' AND d.linked_entity_id=o.id AND d.status='linked') evidence_count FROM obligations o LEFT JOIN sites s ON s.id=o.site_id WHERE o.status NOT IN ('completed','cancelled') AND ((o.current_due_date IS NOT NULL AND o.current_due_date<=?) OR (o.schedule_year=CAST(strftime('%Y','now') AS INTEGER) AND o.schedule_month=CAST(strftime('%m','now') AS INTEGER))) ORDER BY CASE WHEN o.current_due_date<? THEN 0 ELSE 1 END,COALESCE(o.current_due_date,'9999-12-31') LIMIT 20`).all(plus30,today);const payments=db.prepare(`SELECT p.*,v.name vendor_name,s.code site_code,(SELECT COUNT(*) FROM payment_required_docs d WHERE d.payment_id=p.id AND d.required=1 AND d.document_id IS NULL) missing_docs FROM payments p JOIN vendors v ON v.id=p.vendor_id LEFT JOIN sites s ON s.id=p.site_id WHERE p.status NOT IN ('paid','archived') AND (p.contractual_due_date<=? OR EXISTS(SELECT 1 FROM payment_required_docs d WHERE d.payment_id=p.id AND d.required=1 AND d.document_id IS NULL)) ORDER BY COALESCE(p.contractual_due_date,'9999-12-31') LIMIT 12`).all(plus7);const equipment=db.prepare(`SELECT e.*,s.code site_code FROM equipment e LEFT JOIN sites s ON s.id=e.site_id WHERE e.status='active' AND e.next_inspection_date IS NOT NULL AND e.next_inspection_date<=? ORDER BY e.next_inspection_date LIMIT 12`).all(plus30);const inboxCount=(db.prepare("SELECT COUNT(*) c FROM documents WHERE status='needs_review'").get().c+db.prepare("SELECT COUNT(*) c FROM legal_updates WHERE status='needs_review'").get().c+db.prepare("SELECT COUNT(*) c FROM legal_review_queue WHERE status='needs_review'").get().c+db.prepare("SELECT COUNT(*) c FROM deadline_change_requests WHERE status='pending'").get().c);const unread=db.prepare("SELECT COUNT(*) c FROM notifications WHERE status='unread'").get().c;json(res,200,{today,tasks,obligations,payments,equipment,inbox_count:inboxCount,unread_alerts:unread})});

route('GET','/api/notifications',async(req,res,url)=>{refreshNotifications();const status=url.searchParams.get('status')||'',rows=db.prepare(`SELECT * FROM notifications WHERE (?='' OR status=?) ORDER BY CASE level WHEN 'critical' THEN 0 WHEN 'warning' THEN 1 ELSE 2 END,COALESCE(due_date,'9999-12-31'),created_at DESC LIMIT 300`).all(status,status);json(res,200,rows)});
