route('GET','/api/system/health',async(_req,res)=>{const wal=db.prepare('PRAGMA journal_mode').get(),busy=db.prepare('PRAGMA busy_timeout').get(),migs=appliedMigrations(db),lastBackup=tableExistsSafe('backup_history')?db.prepare('SELECT * FROM backup_history WHERE valid=1 ORDER BY created_at DESC LIMIT 1').get():null,lastUpgrade=tableExistsSafe('upgrade_runs')?db.prepare('SELECT * FROM upgrade_runs ORDER BY started_at DESC LIMIT 1').get():null;json(res,200,{app_version:APP_VERSION,db:'ok',journal_mode:Object.values(wal||{})[0],busy_timeout_ms:Object.values(busy||{})[0],legal_watch_enabled:LEGAL_WATCH_ENABLED,users:db.prepare('SELECT COUNT(*) c FROM users WHERE active=1').get().c,documents:db.prepare('SELECT COUNT(*) c FROM documents').get().c,notifications_unread:db.prepare("SELECT COUNT(*) c FROM notifications WHERE status='unread'").get().c,data_home:EHS_HOME_DIR,data_dir:DATA_DIR,upload_dir:UPLOAD_DIR,backup_dir:BACKUP_DIR,db_path:DB_PATH,schema_version:migs.at(-1)?.id||null,migration_count:migs.length,last_backup:lastBackup?{kind:lastBackup.kind,file_name:lastBackup.file_name,created_at:lastBackup.created_at,size_bytes:lastBackup.size_bytes}:null,last_upgrade:lastUpgrade?{from_version:lastUpgrade.from_version,to_version:lastUpgrade.to_version,status:lastUpgrade.status,finished_at:lastUpgrade.finished_at,backup_path:lastUpgrade.backup_path}:null,auto_backup_enabled:AUTO_BACKUP_ENABLED,backup_retention_days:AUTO_BACKUP_RETENTION_DAYS,backup_check_interval_minutes:AUTO_BACKUP_CHECK_INTERVAL_MIN,last_auto_backup_at:metaGet('last_auto_backup_at'),cloud_mode:CLOUD_MODE,personal_private_mode:PERSONAL_PRIVATE_MODE,tailscale_ip:TAILSCALE_IP,listen_host:HOST,listen_port:PORT,remote_url:PUBLIC_BASE_URL,private_access_required:REQUIRE_CF_ACCESS,origin_enforced:ENFORCE_ORIGIN,allowed_hosts:ALLOWED_HOSTS})});
