async function serveStatic(_req,res,pathname){let p=pathname==='/'?'/index.html':pathname;if(p.includes('..'))return false;const file=normalize(join(PUBLIC_DIR,p));if(!file.startsWith(PUBLIC_DIR))return false;try{const data=await readFile(file),ext=extname(file),types={'.html':'text/html; charset=utf-8','.js':'text/javascript; charset=utf-8','.css':'text/css; charset=utf-8','.svg':'image/svg+xml','.png':'image/png'};res.writeHead(200,securityHeaders({'Content-Type':types[ext]||'application/octet-stream','Cache-Control':'no-cache'}));res.end(data);return true}catch{return false}}
function cloudflareAccessAllowed(req,pathname){if(!REQUIRE_CF_ACCESS||pathname==='/healthz')return true;const email=String(req.headers['cf-access-authenticated-user-email']||'').trim().toLowerCase();if(!email)return false;if(!CF_EMAIL_DOMAINS.length)return true;return CF_EMAIL_DOMAINS.some(d=>email.endsWith('@'+d))}
function requestHostAllowed(req){if(!ALLOWED_HOSTS.length)return true;const host=String(req.headers['x-forwarded-host']||req.headers.host||'').split(',')[0].trim().toLowerCase().split(':')[0];return ALLOWED_HOSTS.includes(host)}
function requestOriginAllowed(req){if(!ENFORCE_ORIGIN||!['POST','PUT','PATCH','DELETE'].includes(req.method||''))return true;const origin=String(req.headers.origin||'').trim();if(!origin)return false;if(ALLOWED_ORIGINS.length)return ALLOWED_ORIGINS.includes(origin);try{const u=new URL(origin),host=String(req.headers['x-forwarded-host']||req.headers.host||'').split(',')[0].trim();return u.host===host}catch{return false}}
const server=http.createServer(async(req,res)=>{
  const rawPath=String(req.url||'/').split('?')[0];
  if(!cloudflareAccessAllowed(req,rawPath))return json(res,403,{error:'PRIVATE_ACCESS_REQUIRED'});
  if(rawPath!=='/healthz'&&!requestHostAllowed(req))return json(res,421,{error:'HOST_NOT_ALLOWED'});
  if(!requestOriginAllowed(req))return json(res,403,{error:'ORIGIN_NOT_ALLOWED'});
  const url=new URL(req.url,`http://${req.headers.host||'localhost'}`),r=routes.find(x=>x.method===req.method&&x.pathname===url.pathname);try{if(r){const perm=apiPermission(req.method,url.pathname);if(perm!=='public'){const user=getSessionUser(req);if(!user)return json(res,401,{error:'AUTH_REQUIRED'});req.user=user;if(user.must_change_password&& !['/api/auth/me','/api/auth/change-password','/api/auth/logout'].includes(url.pathname))return json(res,403,{error:'PASSWORD_CHANGE_REQUIRED'});if(perm!=='auth'&&!hasPerm(user,perm))return json(res,403,{error:'FORBIDDEN',permission:perm})}return await r.handler(req,res,url)}if(req.method==='GET'&&await serveStatic(req,res,url.pathname))return;json(res,404,{error:'not found'})}catch(e){console.error(e);json(res,500,{error:e.message||'server error'})}});
server.listen(PORT,HOST,()=>{console.log(`VIETCHEM EHS System CP7.3 NCC Text Input on http://${HOST}:${PORT}`);if(PERSONAL_PRIVATE_MODE){console.log(`[PRIVATE ONLINE] Tailscale-only listener: ${HOST}:${PORT}`);if(PUBLIC_BASE_URL)console.log(`[PRIVATE ONLINE] Open on your tailnet devices: ${PUBLIC_BASE_URL}`)}});
if(LEGAL_WATCH_ENABLED){const min=Math.max(60,Number(process.env.EHS_LEGAL_WATCH_INTERVAL_MIN||1440));const tick=()=>runLegalWatch({triggeredBy:'scheduler'}).then(()=>refreshNotifications()).catch(e=>console.error('Legal watch:',e.message));const first=setTimeout(tick,60_000);first.unref();const timer=setInterval(tick,min*60_000);timer.unref();}
if(AUTO_BACKUP_ENABLED){const tick=()=>maybeAutoBackup().catch(e=>console.error('[BACKUP] Scheduled backup check failed:',e.message||e));const timer=setInterval(tick,AUTO_BACKUP_CHECK_INTERVAL_MIN*60_000);timer.unref();}

